import { Review, User, Comment } from '../types';
import { reviews as initialReviews, currentUser as mockUser, comments as initialComments } from './mockData';

// --- MOCK DATABASE STATE ---
// In a real app, this state lives in Firestore/Cloud SQL
let dbReviews = [...initialReviews];
let dbComments = [...initialComments];

// --- UTILS ---
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// --- API SERVICE ---
// This layer mimics the Cloud Run endpoints described in the Action Plan.
// When the real backend is ready, replace `delay` and mock logic with `fetch('https://api.reviewhub.com/v1/...')`

export const api = {
    auth: {
        login: async (email: string, password: string): Promise<User> => {
            await delay(800); // Simulate network
            // In real app: Firebase Auth
            return mockUser; 
        },
        sendOtp: async (phone: string): Promise<boolean> => {
            await delay(1000); // Simulate Twilio API call
            return true;
        },
        verifyOtp: async (phone: string, code: string): Promise<boolean> => {
            await delay(1200); // Simulate verification check
            if (code === '123456') return true;
            throw new Error('Invalid code');
        }
    },

    reviews: {
        getAll: async (filter: string = 'All'): Promise<Review[]> => {
            await delay(600); // Simulate Firestore query latency

            let results = [...dbReviews];

            // Simulate Filtering Logic
            if (filter !== 'All') {
                if (filter === 'High Risk') {
                    results = results.filter(r => r.isScam || r.tags?.includes('High Risk'));
                } else {
                    // Fuzzy match for category simulation
                    results = results.filter(r => 
                        r.entityType?.toLowerCase().includes(filter.toLowerCase()) || 
                        r.entityName.toLowerCase().includes(filter.toLowerCase())
                    );
                }
            }

            // Sort by newest (simulated)
            return results.sort((a, b) => b.timestamp - a.timestamp);
        },

        getById: async (id: string): Promise<Review | undefined> => {
            await delay(300);
            return dbReviews.find(r => r.id === id);
        },

        create: async (data: Partial<Review>): Promise<Review> => {
            await delay(1500); // Simulate AI Moderation & DB Write

            const newReview: Review = {
                id: Math.random().toString(36).substr(2, 9),
                entityName: data.entityName || 'Unknown',
                entityType: data.entityType || 'General',
                rating: data.rating || 0,
                date: 'Just now',
                timestamp: Date.now(),
                text: data.text || '',
                likes: 0,
                comments: 0,
                user: mockUser,
                images: data.images || [],
                tags: []
            };

            dbReviews = [newReview, ...dbReviews];
            return newReview;
        },

        vote: async (reviewId: string, type: 'up' | 'down'): Promise<number> => {
            // Optimistic update happens in UI, this confirms it
            await delay(200); 
            const review = dbReviews.find(r => r.id === reviewId);
            if (review) {
                review.likes += (type === 'up' ? 1 : -1);
                return review.likes;
            }
            return 0;
        }
    },

    search: {
        // Simulates Algolia Search
        query: async (q: string): Promise<Review[]> => {
            await delay(400);
            if (!q) return [];
            const term = q.toLowerCase();
            return dbReviews.filter(r => 
                r.entityName.toLowerCase().includes(term) || 
                r.text.toLowerCase().includes(term)
            );
        }
    }
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { AppContextType, ViewState, User, ToastMessage } from '../types';
import { api } from '../services/api';

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    // --- Navigation State ---
    const [currentView, setView] = useState<ViewState>('SPLASH');
    const [viewData, setViewData] = useState<any>(null);
    const [history, setHistory] = useState<{view: ViewState, data: any}[]>([]);

    // --- User State ---
    const [currentUser, setCurrentUser] = useState<User | null>(null);

    // --- Theme State ---
    const [isDarkMode, setIsDarkMode] = useState(true);

    // --- Toast State ---
    const [toasts, setToasts] = useState<ToastMessage[]>([]);

    useEffect(() => {
        // Check system preference or persisted theme
        if (isDarkMode) {
            document.documentElement.classList.add('dark');
        } else {
            document.documentElement.classList.remove('dark');
        }
    }, [isDarkMode]);

    const navigate = (view: ViewState, data?: any) => {
        if (view === 'WRITE_REVIEW_MODAL') {
             // Modals don't change the underlying view history usually, but for simplicity:
             setView('WRITE_REVIEW_MODAL');
             return;
        }

        // Back navigation logic could be improved, but this is a simple stack
        setHistory(prev => [...prev, { view: currentView, data: viewData }]);
        setViewData(data);
        setView(view);
        window.scrollTo(0, 0);
    };

    const login = async () => {
        // Simulate login
        const user = await api.auth.login("demo@example.com", "password");
        setCurrentUser(user);
        showToast(`Welcome back, ${user.name}!`, 'success');
    };

    const logout = () => {
        setCurrentUser(null);
        navigate('SPLASH');
        showToast('Logged out successfully', 'info');
    };

    const toggleTheme = () => setIsDarkMode(!isDarkMode);

    const showToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
        const id = Math.random().toString(36).substr(2, 9);
        setToasts(prev => [...prev, { id, message, type }]);
        setTimeout(() => {
            setToasts(prev => prev.filter(t => t.id !== id));
        }, 3000);
    };

    return (
        <AppContext.Provider value={{
            currentView,
            viewData,
            navigate,
            currentUser,
            login,
            logout,
            showToast,
            isDarkMode,
            toggleTheme
        }}>
            {children}
            {/* Global Toast Render */}
            <div className="fixed top-4 left-1/2 -translate-x-1/2 z-[100] flex flex-col gap-2 w-[90%] max-w-sm pointer-events-none">
                {toasts.map(toast => (
                    <div 
                        key={toast.id}
                        className={`animate-fade-in px-4 py-3 rounded-xl shadow-xl flex items-center gap-3 border pointer-events-auto backdrop-blur-md ${
                            toast.type === 'success' ? 'bg-green-500/90 text-white border-green-600' :
                            toast.type === 'error' ? 'bg-red-500/90 text-white border-red-600' :
                            'bg-slate-800/90 text-white border-slate-700'
                        }`}
                    >
                         <span className="material-symbols-outlined text-[20px]">
                            {toast.type === 'success' ? 'check_circle' : toast.type === 'error' ? 'error' : 'info'}
                         </span>
                         <span className="text-sm font-medium">{toast.message}</span>
                    </div>
                ))}
            </div>
        </AppContext.Provider>
    );
};

export const useApp = () => {
    const context = useContext(AppContext);
    if (!context) throw new Error('useApp must be used within AppProvider');
    return context;
};

import React from 'react';

// --- ATOMS ---

interface IconProps {
  name: string;
  filled?: boolean;
  size?: number;
  className?: string;
  onClick?: () => void;
}

export const Icon: React.FC<IconProps> = ({ name, filled = false, size = 24, className = "", onClick }) => (
  <span 
    onClick={onClick}
    className={`material-symbols-outlined ${filled ? 'filled' : ''} ${className} ${onClick ? 'cursor-pointer' : ''} select-none`}
    style={{ fontSize: `${size}px` }}
  >
    {name}
  </span>
);

export const Skeleton = ({ className = "" }: { className?: string }) => (
    <div className={`animate-pulse bg-gray-200 dark:bg-gray-800 rounded ${className}`}></div>
);

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: 'primary' | 'secondary' | 'outline' | 'ghost' | 'danger';
    isLoading?: boolean;
    icon?: string;
}

export const Button: React.FC<ButtonProps> = ({ 
    children, variant = 'primary', isLoading, icon, className = "", ...props 
}) => {
    const base = "relative overflow-hidden h-12 rounded-xl px-5 font-bold text-sm transition-all active:scale-[0.98] disabled:opacity-50 disabled:pointer-events-none flex items-center justify-center gap-2";

    const variants = {
        primary: "bg-primary text-white shadow-lg shadow-primary/25 hover:bg-primary-dark",
        secondary: "bg-surface-dark text-white hover:bg-black",
        outline: "border-2 border-slate-200 dark:border-slate-700 text-slate-900 dark:text-white hover:bg-slate-50 dark:hover:bg-slate-800",
        ghost: "bg-transparent text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-white/5",
        danger: "bg-red-500 text-white shadow-lg shadow-red-500/25 hover:bg-red-600"
    };

    return (
        <button className={`${base} ${variants[variant]} ${className}`} disabled={isLoading} {...props}>
            {isLoading ? (
                <div className="h-5 w-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
            ) : (
                <>
                    {icon && <Icon name={icon} size={20} />}
                    {children}
                </>
            )}
        </button>
    );
};

