import React, { useState } from 'react';
import { Icon, Button } from '../components/Shared';
import { api } from '../services/api';
import { useApp } from '../context/Store';

export const WriteReviewModal = ({ onClose }: { onClose: () => void }) => {
    const { showToast } = useApp();
    const [step, setStep] = useState(1);
    const [isLoading, setIsLoading] = useState(false);

    // Form State
    const [formData, setFormData] = useState({
        entityName: '',
        category: '',
        rating: 0,
        title: '',
        description: '',
    });

    const updateForm = (key: string, value: any) => {
        setFormData(prev => ({ ...prev, [key]: value }));
    };

    const handleSubmit = async () => {
        if (!formData.title || !formData.rating) {
            showToast("Please provide a title and rating", "error");
            return;
        }

        setIsLoading(true);
        try {
            await api.reviews.create({
                entityName: formData.entityName || "New Entity",
                rating: formData.rating,
                text: formData.description,
                entityType: formData.category
            });
            showToast("Review published successfully!", "success");
            onClose();
        } catch (e) {
            showToast("Failed to publish review", "error");
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 z-50 flex flex-col justify-end">
            <div className="absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity" onClick={onClose}></div>

            <div className="relative w-full bg-surface-dark dark:bg-[#111418] rounded-t-3xl shadow-2xl flex flex-col h-[90vh] animate-slide-up text-white overflow-hidden">
                {/* Drag Handle */}
                <div className="w-full flex justify-center pt-3 pb-2 bg-inherit" onClick={onClose}>
                    <div className="h-1.5 w-12 rounded-full bg-gray-600"></div>
                </div>

                <div className="px-6 pb-4 pt-1 flex items-center justify-between shrink-0">
                    <h2 className="text-xl font-bold tracking-tight">Write Review</h2>
                    <button onClick={onClose} className="p-2 -mr-2 text-gray-400 hover:text-white rounded-full hover:bg-white/10 transition-colors">
                        <Icon name="close" />
                    </button>
                </div>

                {/* Progress */}
                <div className="px-6 py-2 shrink-0">
                    <div className="flex items-center gap-2 mb-2">
                        <div className={`h-1 flex-1 rounded-full transition-colors ${step >= 1 ? 'bg-primary' : 'bg-gray-700'}`}></div>
                        <div className={`h-1 flex-1 rounded-full transition-colors ${step >= 2 ? 'bg-primary' : 'bg-gray-700'}`}></div>
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto px-6 pt-2 pb-24 no-scrollbar">
                    {step === 1 ? (
                        <div className="space-y-6 animate-fade-in">
                            <div>
                                <label className="block text-sm font-medium text-gray-300 mb-3">What are you reviewing?</label>
                                <input 
                                    className="w-full bg-[#1c2128] border border-gray-700 rounded-xl px-4 py-4 text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-primary/50 transition-all" 
                                    placeholder="Business name, phone number, product..."
                                    value={formData.entityName}
                                    onChange={(e) => updateForm('entityName', e.target.value)}
                                    autoFocus
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-300 mb-3">Category</label>
                                <div className="flex gap-3 flex-wrap">
                                    {['Dining', 'Service', 'Product', 'Scam Report'].map(cat => (
                                        <button 
                                            key={cat}
                                            onClick={() => updateForm('category', cat)}
                                            className={`flex h-10 items-center justify-center px-5 rounded-full border transition-all ${formData.category === cat ? 'bg-primary border-primary text-white shadow-lg shadow-primary/20' : 'bg-transparent border-gray-600 text-gray-300 hover:border-gray-400'}`}
                                        >
                                            <span className="text-sm font-medium">{cat}</span>
                                        </button>
                                    ))}
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-300 mb-3">Rate your experience</label>
                                <div className="flex items-center justify-between bg-[#1c2128] p-4 rounded-xl border border-gray-700">
                                    {[1, 2, 3, 4, 5].map((star) => (
                                        <button key={star} onClick={() => updateForm('rating', star)} className="group transition-transform active:scale-75">
                                            <Icon 
                                                name="star" 
                                                filled={star <= formData.rating} 
                                                size={36} 
                                                className={`transition-colors ${star <= formData.rating ? "text-amber-400 drop-shadow-md" : "text-gray-600"}`} 
                                            />
                                        </button>
                                    ))}
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="space-y-6 animate-fade-in">
                            <div>
                                <label className="block text-sm font-medium text-gray-300 mb-2">Review Title</label>
                                <input 
                                    className="w-full bg-[#1c2128] border border-gray-700 rounded-xl px-4 py-4 text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-primary/50" 
                                    placeholder="Sum it up in a few words"
                                    value={formData.title}
                                    onChange={(e) => updateForm('title', e.target.value)} 
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-300 mb-2">Details</label>
                                <textarea 
                                    className="w-full bg-[#1c2128] border border-gray-700 rounded-xl px-4 py-4 h-40 resize-none focus:outline-none focus:ring-2 focus:ring-primary/50 text-white placeholder-gray-500" 
                                    placeholder="What was great? What could be better?"
                                    value={formData.description}
                                    onChange={(e) => updateForm('description', e.target.value)} 
                                ></textarea>
                            </div>
                        </div>
                    )}
                </div>

                <div className="absolute bottom-0 left-0 right-0 bg-[#111418] border-t border-[#282f39] p-4 pb-8 flex gap-3 z-30">
                    {step === 2 && (
                        <Button variant="secondary" onClick={() => setStep(1)} className="flex-1">Back</Button>
                    )}
                    <Button 
                        variant="primary" 
                        onClick={() => step === 1 ? setStep(2) : handleSubmit()} 
                        isLoading={isLoading}
                        className={step === 1 ? "w-full" : "flex-[2]"}
                    >
                        {step === 1 ? 'Next' : 'Submit Review'}
                    </Button>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { useApp } from '../context/Store';
import { api } from '../services/api';
import { Review } from '../types';
import { Icon, Skeleton } from '../components/Shared';

export const Search = () => {
    const { navigate } = useApp();
    const [query, setQuery] = useState('');
    const [results, setResults] = useState<Review[]>([]);
    const [isSearching, setIsSearching] = useState(false);

    // Debounce Search
    useEffect(() => {
        const timer = setTimeout(async () => {
            if (query.length > 2) {
                setIsSearching(true);
                const data = await api.search.query(query);
                setResults(data);
                setIsSearching(false);
            } else {
                setResults([]);
            }
        }, 500);

        return () => clearTimeout(timer);
    }, [query]);

    return (
        <div className="flex flex-col h-full bg-background-light dark:bg-background-dark animate-fade-in">
            <header className="sticky top-0 z-50 bg-white dark:bg-background-dark border-b border-gray-100 dark:border-gray-800 pb-2">
                <div className="flex items-center px-4 pt-4 pb-2 gap-3">
                    <button onClick={() => navigate('HOME')} className="flex items-center justify-center size-10 text-primary hover:bg-slate-50 dark:hover:bg-white/5 rounded-full transition-colors shrink-0">
                        <Icon name="arrow_back" />
                    </button>
                    <div className="flex-1 relative">
                        <div className="flex w-full items-center rounded-2xl bg-slate-100 dark:bg-surface-dark h-12 px-4 focus-within:ring-2 focus-within:ring-primary/50 transition-all">
                            <Icon name="search" className="text-gray-400" size={22} />
                            <input 
                                className="w-full bg-transparent border-none focus:ring-0 text-base text-slate-900 dark:text-white placeholder-gray-400 px-3 font-normal" 
                                type="text" 
                                placeholder="Search everything..."
                                value={query}
                                onChange={(e) => setQuery(e.target.value)}
                                autoFocus
                            />
                            {query && (
                                <button onClick={() => setQuery('')}>
                                    <Icon name="cancel" filled className="text-gray-400 hover:text-gray-600" size={20} />
                                </button>
                            )}
                        </div>
                    </div>
                </div>
            </header>

            <main className="flex-1 flex flex-col p-4 gap-3 overflow-y-auto">
                {isSearching ? (
                    [1,2,3].map(i => <Skeleton key={i} className="h-24 w-full rounded-xl" />)
                ) : results.length > 0 ? (
                    results.map(result => (
                        <div 
                            key={result.id}
                            onClick={() => navigate('REVIEW_DETAILS', result)}
                            className="bg-white dark:bg-surface-dark rounded-xl p-4 shadow-sm active:scale-[0.98] transition-all cursor-pointer border border-gray-100 dark:border-gray-800"
                        >
                            <div className="flex justify-between items-start mb-1">
                                <h3 className="font-bold text-slate-900 dark:text-white">{result.entityName}</h3>
                                <span className="text-xs text-gray-500">{result.rating.toFixed(1)} ★</span>
                            </div>
                            <p className="text-sm text-slate-600 dark:text-slate-400 line-clamp-2">{result.text}</p>
                        </div>
                    ))
                ) : query.length > 0 ? (
                    <div className="flex flex-col items-center justify-center pt-20 text-gray-400">
                        <Icon name="search_off" size={48} className="mb-2 opacity-50" />
                        <p>No results found for "{query}"</p>
                    </div>
                ) : (
                    <div className="pt-4">
                        <h4 className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-4 px-2">Recent Searches</h4>
                        <div className="flex flex-wrap gap-2">
                            {['iPhone 15', 'Scam calls', 'Best Pizza'].map(t => (
                                <button key={t} onClick={() => setQuery(t)} className="px-4 py-2 bg-white dark:bg-surface-dark border border-gray-200 dark:border-gray-700 rounded-lg text-sm font-medium text-slate-700 dark:text-slate-300">
                                    {t}
                                </button>
                            ))}
                        </div>
                    </div>
                )}
            </main>
        </div>
    );
};

