import { Review, User, Comment } from '../types';
import { reviews as initialReviews, currentUser as mockUser, comments as initialComments } from './mockData';
import { GoogleGenAI } from "@google/genai";

// --- MOCK DATABASE STATE ---
// In a real app, this state lives in Firestore/Cloud SQL
let dbReviews = [...initialReviews];
let dbComments = [...initialComments];

// --- UTILS ---
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// --- API SERVICE ---
// This layer mimics the Cloud Run endpoints described in the Action Plan.
// When the real backend is ready, replace `delay` and mock logic with `fetch('https://api.reviewhub.com/v1/...')`

export const api = {
    auth: {
        login: async (email: string, password: string): Promise<User> => {
            await delay(800); // Simulate network
            // In real app: Firebase Auth
            return mockUser; 
        },
        sendOtp: async (phone: string): Promise<boolean> => {
            await delay(1000); // Simulate Twilio API call
            return true;
        },
        verifyOtp: async (phone: string, code: string): Promise<boolean> => {
            await delay(1200); // Simulate verification check
            if (code === '123456') return true;
            throw new Error('Invalid code');
        }
    },

    reviews: {
        getAll: async (filter: string = 'All'): Promise<Review[]> => {
            await delay(600); // Simulate Firestore query latency

            let results = [...dbReviews];

            // Simulate Filtering Logic
            if (filter !== 'All') {
                if (filter === 'High Risk') {
                    results = results.filter(r => r.isScam || r.tags?.includes('High Risk'));
                } else {
                    // Fuzzy match for category simulation
                    results = results.filter(r => 
                        r.entityType?.toLowerCase().includes(filter.toLowerCase()) || 
                        r.entityName.toLowerCase().includes(filter.toLowerCase())
                    );
                }
            }

            // Sort by newest (simulated)
            return results.sort((a, b) => b.timestamp - a.timestamp);
        },

        getById: async (id: string): Promise<Review | undefined> => {
            await delay(300);
            return dbReviews.find(r => r.id === id);
        },

        create: async (data: Partial<Review>): Promise<Review> => {
            await delay(1500); // Simulate AI Moderation & DB Write

            const newReview: Review = {
                id: Math.random().toString(36).substr(2, 9),
                entityName: data.entityName || 'Unknown',
                entityType: data.entityType || 'General',
                rating: data.rating || 0,
                date: 'Just now',
                timestamp: Date.now(),
                text: data.text || '',
                likes: 0,
                comments: 0,
                user: mockUser,
                images: data.images || [],
                tags: data.tags || [],
                meta: data.meta, // Persist structured metadata
                isScam: data.isScam || false
            };

            dbReviews = [newReview, ...dbReviews];
            return newReview;
        },

        vote: async (reviewId: string, type: 'up' | 'down'): Promise<number> => {
            // Optimistic update happens in UI, this confirms it
            await delay(200); 
            const review = dbReviews.find(r => r.id === reviewId);
            if (review) {
                review.likes += (type === 'up' ? 1 : -1);
                return review.likes;
            }
            return 0;
        }
    },

    search: {
        // Simulates Algolia Search
        query: async (q: string): Promise<Review[]> => {
            await delay(400);
            if (!q) return [];
            const term = q.toLowerCase();
            return dbReviews.filter(r => 
                r.entityName.toLowerCase().includes(term) || 
                r.text.toLowerCase().includes(term)
            );
        }
    },

    ai: {
        analyzeReview: async (text: string, entity: string): Promise<string> => {
            // Only proceed if API KEY is available (production or local env)
            if (!process.env.API_KEY) {
                await delay(1000); // Mock delay
                return "AI Analysis Unavailable: API Key missing. In production, this would provide a trust score and summary.";
            }

            try {
                const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
                const response = await ai.models.generateContent({
                    model: 'gemini-3-flash-preview',
                    contents: `You are a helpful assistant for a review platform called ReviewHub. 
                    Analyze the following review for the entity "${entity}".
                    Review text: "${text}"

                    Please provide:
                    1. A "Trust Score" (1-10) based on the review's detail and sentiment.
                    2. A one-sentence summary of the key pros/cons.
                    3. If it looks like a scam or spam, flag it.

                    Format the response as a short paragraph.`,
                });
                return response.text || "Unable to generate analysis.";
            } catch (error) {
                console.error("Gemini API Error:", error);
                return "AI Analysis failed temporarily.";
            }
        }
    }
};

