export const WriteReviewModal = ({ onClose }: { onClose: () => void }) => {
    const { showToast } = useApp();
    const [step, setStep] = useState(0); // 0: Category, 1: Details, 2: Rating/Content
    const [isLoading, setIsLoading] = useState(false);

    // State
    const [categoryId, setCategoryId] = useState<string | null>(null);
    const [entityName, setEntityName] = useState(''); // Stores Vehicle Number for Ride Share

    // Optional extras
    const [driverName, setDriverName] = useState(''); 
    const [phoneNumber, setPhoneNumber] = useState('');

    const [selectedPlatform, setSelectedPlatform] = useState('');
    const [selectedIssues, setSelectedIssues] = useState<string[]>([]);
    const [rating, setRating] = useState(0);
    const [description, setDescription] = useState('');

    const config = categoryId ? FORM_CONFIG[categoryId] : null;

    const toggleIssue = (issue: string) => {
        setSelectedIssues(prev => 
            prev.includes(issue) ? prev.filter(i => i !== issue) : [...prev, issue]
        );
    };

    const handleSubmit = async () => {
        if (!entityName || rating === 0) {
            showToast("Please fill in the required fields", "error");
            return;
        }

        setIsLoading(true);
        try {
            // Construct structured Data
            const metaData: any = {
                platform: selectedPlatform,
                issues: selectedIssues,
                category: categoryId,
            };

            // Add Ride Share specific extras
            if (categoryId === 'ride_share') {
                if (driverName) metaData.driverName = driverName;
                if (phoneNumber) metaData.phoneNumber = phoneNumber;
            }

            const isScam = selectedIssues.some(i => 
                ['Scam', 'Fraud', 'No Delivery', 'Fake Item', 'Lottery Scam', 'Bank OTP Scam', 'Blocked Me'].some(keyword => i.includes(keyword))
            ) || categoryId === 'phone_scam';

            const tags = [
                ...(isScam ? ['High Risk'] : []),
                ...(selectedPlatform ? [selectedPlatform] : []),
                CATEGORIES.find(c => c.id === categoryId)?.label || 'General'
            ];

            await api.reviews.create({
                entityName: entityName,
                entityType: CATEGORIES.find(c => c.id === categoryId)?.label,
                rating: rating,
                text: description,
                isScam: isScam,
                tags: tags,
                meta: metaData
            });

            showToast("Review published successfully!", "success");
            onClose();
