import React, { useState, useEffect } from 'react';
import { Icon, Button } from '../components/Shared';
import { api } from '../services/api';
import { useApp } from '../context/Store';
import { REVIEW_CONFIG, CategoryConfig } from '../services/reviewConfig';

export const WriteReviewModal = ({ onClose }: { onClose: () => void }) => {
    const { showToast } = useApp();
    const [step, setStep] = useState(0); // 0: Category, 1: Details
    const [isLoading, setIsLoading] = useState(false);

    // State
    const [selectedCategory, setSelectedCategory] = useState<CategoryConfig | null>(null);
    const [entityName, setEntityName] = useState(''); 

    // Dynamic Extras
    const [extraData, setExtraData] = useState<Record<string, string>>({});

    const [recommendedContact, setRecommendedContact] = useState('');
    const [isSameContact, setIsSameContact] = useState(false); // State for "Same as above" checkbox

    const [selectedPlatform, setSelectedPlatform] = useState('');
    const [selectedIssues, setSelectedIssues] = useState<string[]>([]);
    const [rating, setRating] = useState(0);
    const [description, setDescription] = useState('');

    // Reset issues when rating changes significantly
    useEffect(() => {
        setSelectedIssues([]);
    }, [rating < 4]);

    // Sync phone number to recommended contact if checkbox is checked
    // We look for a secondary input with id 'phoneNumber'
    useEffect(() => {
        const phoneValue = extraData['phoneNumber'];
        if (isSameContact && phoneValue) {
            setRecommendedContact(phoneValue);
        }
    }, [extraData, isSameContact]);

    const handleExtraChange = (id: string, value: string) => {
        setExtraData(prev => ({ ...prev, [id]: value }));

        // Auto-update recommended contact if "Same as above" is checked and we are editing phone
        if (id === 'phoneNumber' && isSameContact) {
            setRecommendedContact(value);
        }
    };

    const toggleIssue = (issue: string) => {
        setSelectedIssues(prev => 
            prev.includes(issue) ? prev.filter(i => i !== issue) : [...prev, issue]
        );
    };

    const handleSubmit = async () => {
        if (!entityName || rating === 0 || !selectedCategory) {
            showToast("Please fill in the required fields", "error");
            return;
        }

        setIsLoading(true);
        try {
            // Construct structured Data
            const metaData: any = {
                platform: selectedPlatform,
                issues: selectedIssues,
                category: selectedCategory.id,
                ...extraData // Spread dynamic inputs into metadata
            };

            if (rating >= 4 && recommendedContact) {
                metaData.recommendedContact = recommendedContact;
            }

            const isScam = selectedIssues.some(i => 
                ['Scam', 'Fraud', 'No Delivery', 'Fake Item', 'Lottery Scam', 'Bank OTP Scam', 'Blocked Me'].some(keyword => i.includes(keyword))
            ) || selectedCategory.id === 'phone_scam' || rating === 1;

            const tags = [
                ...(isScam ? ['High Risk'] : []),
                ...(rating >= 4 ? ['Recommended'] : []),
                ...(selectedPlatform ? [selectedPlatform] : []),
                selectedCategory.label
            ];

            await api.reviews.create({
                entityName: entityName,
                entityType: selectedCategory.label,
                rating: rating,
                text: description,
                isScam: isScam,
                tags: tags,
                meta: metaData
            });

            showToast("Review published successfully!", "success");
            onClose();
        } catch (e) {
            showToast("Failed to publish review", "error");
        } finally {
            setIsLoading(false);
        }
    };

    const renderCategoryStep = () => (
        <div className="animate-fade-in px-1">
            <h3 className="text-xl font-bold text-white mb-2">What kind of review is this?</h3>
            <p className="text-gray-400 text-sm mb-6">Select a category to help us ask the right questions.</p>

            <div className="grid grid-cols-2 gap-3 pb-8">
                {REVIEW_CONFIG.map(cat => (
                    <button
                        key={cat.id}
                        onClick={() => { setSelectedCategory(cat); setStep(1); }}
                        className={`flex flex-col items-center justify-center p-4 rounded-2xl border transition-all active:scale-95 hover:bg-white/5 ${cat.color}`}
                    >
                        <Icon name={cat.icon} size={32} className="mb-2" />
                        <span className="font-bold text-sm text-gray-200">{cat.label}</span>
                    </button>
                ))}
            </div>
        </div>
    );

    const renderDetailsStep = () => {
        if (!selectedCategory) return null;

        let displayedTags: string[] = [];
        if (rating > 0) {
            displayedTags = rating >= 4 ? selectedCategory.tags.positive : selectedCategory.tags.negative;
        }

        return (
            <div className="animate-slide-up space-y-6 pb-20">
                {/* 1. Identity Inputs */}
                <div>
                    <label className="block text-xs font-bold uppercase tracking-wider text-gray-400 mb-2">{selectedCategory.inputLabel} <span className="text-red-500">*</span></label>
                    <input 
                        className="w-full bg-[#1c2128] border border-gray-700 rounded-xl px-4 py-4 text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-primary/50 text-lg transition-all" 
                        placeholder={selectedCategory.inputPlaceholder}
                        value={entityName}
                        onChange={(e) => setEntityName(e.target.value)}
                        autoFocus
                    />
                </div>

                {/* Conditional Inputs from Config (Dynamic) */}
                {selectedCategory.secondaryInputs && selectedCategory.secondaryInputs.length > 0 && (
                    <div className="grid grid-cols-2 gap-4">
                        {selectedCategory.secondaryInputs.map(input => (
                             <div key={input.id}>
                                <label className="block text-xs font-bold uppercase tracking-wider text-gray-500 mb-2">{input.label}</label>
                                <input 
                                    className="w-full bg-[#1c2128] border border-gray-700 rounded-xl px-4 py-3 text-white placeholder-gray-600 focus:outline-none focus:ring-2 focus:ring-primary/50 text-sm" 
                                    placeholder={input.placeholder}
                                    type={input.type}
                                    value={extraData[input.id] || ''}
                                    onChange={(e) => handleExtraChange(input.id, e.target.value)}
                                />
                            </div>
                        ))}
                    </div>
                )}

                {/* 2. Platform Selection */}
                {selectedCategory.platforms.length > 0 && (
                    <div>
                        <label className="block text-xs font-bold uppercase tracking-wider text-gray-400 mb-3">Platform / Method</label>
                        <div className="flex flex-wrap gap-2">
                            {selectedCategory.platforms.map((p: string) => (
                                <button
                                    key={p}
                                    onClick={() => setSelectedPlatform(p)}
                                    className={`px-4 py-2 rounded-full text-sm font-medium border transition-all ${
                                        selectedPlatform === p 
                                        ? 'bg-primary border-primary text-white shadow-lg shadow-primary/20' 
                                        : 'bg-transparent border-gray-600 text-gray-300 hover:border-gray-400'
                                    }`}
                                >
                                    {p}
                                </button>
                            ))}
                        </div>
                    </div>
                )}

                {/* 3. Rating (Modernized & Minimal) */}
                <div className="flex flex-col items-center py-2">
                    <div className="flex items-center gap-3">
                        {[1, 2, 3, 4, 5].map((star) => (
                            <button 
                                key={star} 
                                onClick={() => setRating(star)} 
                                className="group transition-transform active:scale-95 focus:outline-none"
                            >
                                <Icon 
                                    name="star" 
                                    filled={star <= rating} 
                                    size={36} 
                                    className={`transition-all duration-200 ${
                                        star <= rating 
                                        ? "text-amber-400 drop-shadow-[0_0_8px_rgba(251,191,36,0.3)]" 
                                        : "text-gray-700 dark:text-gray-600 hover:text-gray-500"
                                    }`} 
                                />
                            </button>
                        ))}
                    </div>
                    <div className={`mt-3 h-5 flex items-center justify-center transition-all duration-300 ${rating > 0 ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-2'}`}>
                        <span className={`text-sm font-bold tracking-wider ${
                            rating >= 4 ? 'text-green-400' : 
                            rating === 3 ? 'text-yellow-400' : 
                            'text-red-400'
                        }`}>
                            {rating === 1 ? "Terrible" : rating === 2 ? "Bad" : rating === 3 ? "Okay" : rating === 4 ? "Good" : rating === 5 ? "Excellent" : ""}
                        </span>
                    </div>
                </div>

                {/* 4. Dynamic Highlights (Pill Shaped) */}
                {rating > 0 && displayedTags.length > 0 && (
                    <div className="animate-fade-in">
                        <label className="block text-xs font-bold uppercase tracking-wider text-gray-400 mb-3">
                            {rating >= 4 ? "What went well?" : "What went wrong?"}
                        </label>
                        <div className="flex flex-wrap gap-2">
                            {displayedTags.map((issue: string) => {
                                const isSelected = selectedIssues.includes(issue);
                                const isPositive = rating >= 4;

                                return (
                                    <button
                                        key={issue}
                                        onClick={() => toggleIssue(issue)}
                                        className={`px-4 py-2 rounded-full text-sm font-medium border transition-all ${
                                            isSelected 
                                                ? (isPositive 
                                                    ? 'bg-green-500/20 border-green-500 text-green-400' 
                                                    : 'bg-red-500/20 border-red-500 text-red-400')
                                                : 'bg-transparent border-gray-700 text-gray-400 hover:border-gray-500'
                                        }`}
                                    >
                                        {issue}
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                )}

                {/* 5. Conditional Contact Info */}
                {rating >= 4 && (
                    <div className="animate-fade-in bg-green-500/5 p-4 rounded-xl border border-green-500/20">
                        <div className="flex items-start gap-3 mb-3">
                            <Icon name="verified" className="text-green-500 mt-1" size={20} />
                            <div>
                                <h4 className="font-bold text-green-400 text-sm">Help others find this!</h4>
                                <p className="text-xs text-gray-400">Add a contact number so others can hire this person/service.</p>
                            </div>
                        </div>

                        {/* Same as above Checkbox - Only show if a phone number field exists and has value */}
                        {extraData['phoneNumber'] && extraData['phoneNumber'].length > 0 && (
                            <label className="flex items-center gap-2 mb-3 cursor-pointer group w-fit select-none">
                                <div className={`w-4 h-4 rounded border flex items-center justify-center transition-colors ${isSameContact ? 'bg-green-500 border-green-500' : 'border-gray-500 group-hover:border-green-500'}`}>
                                    {isSameContact && <Icon name="check" size={12} className="text-white font-bold" />}
                                </div>
                                <input 
                                    type="checkbox" 
                                    className="hidden"
                                    checked={isSameContact}
                                    onChange={(e) => setIsSameContact(e.target.checked)}
                                />
                                <span className={`text-xs font-medium transition-colors ${isSameContact ? 'text-green-400' : 'text-gray-400 group-hover:text-gray-300'}`}>
                                    Same as above
                                </span>
                            </label>
                        )}

                        <input 
                            className="w-full bg-[#111418] border border-gray-700 rounded-lg px-4 py-3 text-white placeholder-gray-600 focus:outline-none focus:ring-1 focus:ring-green-500 text-sm" 
                            placeholder="Recommended Contact Number (Optional)"
                            type="tel"
                            value={recommendedContact}
                            onChange={(e) => {
                                setRecommendedContact(e.target.value);
                                if (isSameContact) setIsSameContact(false);
                            }}
                        />
                    </div>
                )}

                {/* 6. Description */}
                <div>
                    <label className="block text-xs font-bold uppercase tracking-wider text-gray-400 mb-2">Description (Optional)</label>
                    <textarea 
                        className="w-full bg-[#1c2128] border border-gray-700 rounded-xl px-4 py-4 h-32 resize-none focus:outline-none focus:ring-2 focus:ring-primary/50 text-white placeholder-gray-500 text-base" 
                        placeholder="Tell others about your experience..."
                        value={description}
                        onChange={(e) => setDescription(e.target.value)} 
                    ></textarea>
                </div>
            </div>
        );
    };

    return (
        <div className="fixed inset-0 z-50 flex flex-col justify-end">
            <div className="absolute inset-0 bg-black/80 backdrop-blur-sm transition-opacity" onClick={onClose}></div>

            <div className="relative w-full bg-surface-dark dark:bg-[#111418] rounded-t-3xl shadow-2xl flex flex-col h-[92vh] animate-slide-up text-white overflow-hidden border-t border-white/10">
                {/* Header */}
                <div className="px-6 py-4 flex items-center justify-between shrink-0 border-b border-white/5 bg-[#111418] z-20">
                    <div className="flex items-center gap-3">
                        {step > 0 && (
                            <button onClick={() => setStep(step - 1)} className="p-1 rounded-full hover:bg-white/10 text-gray-400">
                                <Icon name="arrow_back" size={20} />
                            </button>
                        )}
                        <h2 className="text-lg font-bold tracking-tight">
                            {step === 0 ? "New Review" : selectedCategory?.title}
                        </h2>
                    </div>
                    <button onClick={onClose} className="p-2 -mr-2 text-gray-400 hover:text-white rounded-full hover:bg-white/10 transition-colors">
                        <Icon name="close" />
                    </button>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto px-6 py-6 no-scrollbar relative">
                    {step === 0 && renderCategoryStep()}
                    {step === 1 && renderDetailsStep()}
                </div>

                {/* Footer Actions */}
                {step > 0 && (
                    <div className="p-4 border-t border-white/10 bg-[#111418] z-20 pb-8">
                        <Button 
                            variant="primary" 
                            onClick={handleSubmit} 
                            isLoading={isLoading}
                            className="w-full text-base"
                            disabled={!entityName || rating === 0}
                        >
                            Submit Review
                        </Button>
                    </div>
                )}
            </div>
        </div>
    );
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { AppContextType, ViewState, User, ToastMessage } from '../types';
import { api } from '../services/api';

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    // --- Navigation State ---
    const [currentView, setView] = useState<ViewState>('HOME');
    const [viewData, setViewData] = useState<any>(null);
    const [history, setHistory] = useState<{view: ViewState, data: any}[]>([]);

    // --- User State ---
    const [currentUser, setCurrentUser] = useState<User | null>(null);

    // --- Theme State ---
    const [isDarkMode, setIsDarkMode] = useState(true);

    // --- Toast State ---
    const [toasts, setToasts] = useState<ToastMessage[]>([]);

    useEffect(() => {
        // Check system preference or persisted theme
        if (isDarkMode) {
            document.documentElement.classList.add('dark');
        } else {
            document.documentElement.classList.remove('dark');
        }
    }, [isDarkMode]);

    const navigate = (view: ViewState, data?: any) => {
        if (view === 'WRITE_REVIEW_MODAL') {
             // Modals don't change the underlying view history usually, but for simplicity:
             setView('WRITE_REVIEW_MODAL');
             return;
        }

        // Back navigation logic could be improved, but this is a simple stack
        setHistory(prev => [...prev, { view: currentView, data: viewData }]);
        setViewData(data);
        setView(view);
        window.scrollTo(0, 0);
    };

    const login = async () => {
        // Simulate login
        const user = await api.auth.login("demo@example.com", "password");
        setCurrentUser(user);
        showToast(`Welcome back, ${user.name}!`, 'success');
    };

    const logout = () => {
        setCurrentUser(null);
        navigate('HOME');
        showToast('Logged out successfully', 'info');
    };

    const toggleTheme = () => setIsDarkMode(!isDarkMode);

    const showToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
        const id = Math.random().toString(36).substr(2, 9);
        setToasts(prev => [...prev, { id, message, type }]);
        setTimeout(() => {
            setToasts(prev => prev.filter(t => t.id !== id));
        }, 3000);
    };

    return (
        <AppContext.Provider value={{
            currentView,
            viewData,
            navigate,
            currentUser,
            login,
            logout,
            showToast,
            isDarkMode,
            toggleTheme
        }}>
            {children}
            {/* Global Toast Render */}
            <div className="fixed top-4 left-1/2 -translate-x-1/2 z-[100] flex flex-col gap-2 w-[90%] max-w-sm pointer-events-none">
                {toasts.map(toast => (
                    <div 
                        key={toast.id}
                        className={`animate-fade-in px-4 py-3 rounded-xl shadow-xl flex items-center gap-3 border pointer-events-auto backdrop-blur-md ${
                            toast.type === 'success' ? 'bg-green-500/90 text-white border-green-600' :
                            toast.type === 'error' ? 'bg-red-500/90 text-white border-red-600' :
                            'bg-slate-800/90 text-white border-slate-700'
                        }`}
                    >
                         <span className="material-symbols-outlined text-[20px]">
                            {toast.type === 'success' ? 'check_circle' : toast.type === 'error' ? 'error' : 'info'}
                         </span>
                         <span className="text-sm font-medium">{toast.message}</span>
                    </div>
                ))}
            </div>
        </AppContext.Provider>
    );
};

export const useApp = () => {
    const context = useContext(AppContext);
    if (!context) throw new Error('useApp must be used within AppProvider');
    return context;
};

import React from 'react';
import { ViewState } from './types';
import { AppProvider, useApp } from './context/Store';
import { BottomNav } from './components/Shared';

// Pages
import { Splash } from './pages/Splash';
import { Home } from './pages/Home';
import { Search } from './pages/Search';
import { ReviewDetails } from './pages/ReviewDetails';
import { Profile } from './pages/Profile';
import { MyReviews } from './pages/MyReviews';
import { WriteReviewModal } from './pages/WriteReviewModal';
import { Verify } from './pages/Verify';

const AppContent = () => {
  const { currentView, viewData, navigate, currentUser, login, showToast } = useApp();

  const handleNavigate = (view: string) => {
    // Intercept Add Review action if not logged in
    if (view === 'WRITE_REVIEW_MODAL' && !currentUser) {
        showToast("Please login to write a review", "info");
        login();
        return;
    }
    navigate(view as ViewState);
  };

  const renderView = () => {
    switch (currentView) {
      case 'SPLASH': return <Splash navigate={navigate} />;
      case 'HOME': return <Home />;
      case 'SEARCH': return <Search />;
      case 'REVIEW_DETAILS': return <ReviewDetails review={viewData} />;
      case 'PROFILE': return <Profile />;
      case 'MY_REVIEWS': return <MyReviews navigate={navigate} onReviewClick={(r) => navigate('REVIEW_DETAILS', r)} />;
      case 'VERIFY': return <Verify />;
      default: return <Home />;
    }
  };

  const showNav = ['HOME', 'PROFILE', 'SEARCH'].includes(currentView);

  return (
    <div className="max-w-md mx-auto bg-white dark:bg-background-dark min-h-screen relative shadow-2xl overflow-hidden font-sans">
      {renderView()}

      {showNav && (
        <BottomNav 
            activeTab={currentView} 
            onNavigate={handleNavigate} 
        />
      )}

      {currentView === 'WRITE_REVIEW_MODAL' && (
        <WriteReviewModal onClose={() => navigate('HOME')} />
      )}
    </div>
  );
};

const App = () => (
    <AppProvider>
        <AppContent />
    </AppProvider>
);

export default App;

import React, { useState } from 'react';
import { useApp } from '../context/Store';
import { Review, Comment } from '../types';
import { comments as initialComments } from '../services/mockData';
import { Icon, Header, Button } from '../components/Shared';
import { api } from '../services/api';

export const ReviewDetails = ({ review }: { review: Review }) => {
    const { navigate, showToast, currentUser, login } = useApp();
    const [likes, setLikes] = useState(review?.likes || 0);
    const [hasLiked, setHasLiked] = useState(false);

    // Comments State
    const [commentsList, setCommentsList] = useState<Comment[]>(initialComments);
    const [commentText, setCommentText] = useState('');
    const [isPosting, setIsPosting] = useState(false);

    if (!review) return null;

    const handleLike = async () => {
        if (!currentUser) {
            showToast("Please login to vote", "info");
            login();
            return;
        }

        // Optimistic Update
        const newHasLiked = !hasLiked;
        setHasLiked(newHasLiked);
        setLikes(prev => newHasLiked ? prev + 1 : prev - 1);

        try {
            await api.reviews.vote(review.id, newHasLiked ? 'up' : 'down');
        } catch (e) {
            // Revert on error
            setHasLiked(!newHasLiked);
            setLikes(prev => !newHasLiked ? prev + 1 : prev - 1);
            showToast("Failed to vote", "error");
        }
    };

    const handlePostComment = async () => {
        if (!currentUser) return;
        if (!commentText.trim()) return;

        setIsPosting(true);
        try {
            const newComment = await api.reviews.addComment(review.id, commentText, currentUser);
            setCommentsList(prev => [newComment, ...prev]);
            setCommentText('');
            showToast("Comment posted!", "success");
        } catch (e) {
            showToast("Failed to post comment", "error");
        } finally {
            setIsPosting(false);
        }
    };

    return (
        <div className="relative min-h-screen w-full flex flex-col bg-background-light dark:bg-background-dark pb-24 animate-fade-in">
            <Header 
                title="Review Details" 
                showBack 
                onBack={() => navigate('HOME')} 
                rightAction={
                    <button className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-white/10 text-slate-900 dark:text-white">
                        <Icon name="share" size={20} />
                    </button>
                }
            />

            {/* Hero Section */}
            <div className="px-5 pt-4 pb-6 bg-white dark:bg-background-dark border-b border-gray-100 dark:border-gray-800">
                <div className="flex flex-col gap-3">
                    <div className="flex items-start justify-between">
                        <div>
                            <h2 className="text-3xl font-black tracking-tight text-slate-900 dark:text-white leading-tight mb-2">{review.entityName}</h2>
                            <div className="flex items-center gap-2 text-sm">
                                <span className="bg-gray-100 dark:bg-gray-800 px-2 py-1 rounded text-gray-600 dark:text-gray-300 font-medium">{review.entityType || 'Business'}</span>
                                <span className="text-gray-400">•</span>
                                <span className="text-gray-500">{review.date}</span>
                            </div>
                        </div>
                        <div className="flex flex-col items-end gap-1">
                            <div className="flex items-center justify-center h-12 w-12 rounded-xl bg-amber-100 dark:bg-amber-900/30 text-amber-600 dark:text-amber-400">
                                <span className="text-lg font-black">{review.rating}</span>
                            </div>
                            <div className="flex text-amber-400 text-[10px]">
                                {[1,2,3,4,5].map(i => <Icon key={i} name="star" filled={i <= Math.round(review.rating)} size={12} />)}
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <main className="flex-1 px-4 pt-6 flex flex-col gap-6">
                <article className="bg-white dark:bg-surface-dark rounded-2xl shadow-sm border border-gray-100 dark:border-gray-800 p-5">
                    {/* User Info */}
                    <div className="flex items-center justify-between mb-5">
                        <div className="flex items-center gap-3">
                            <div className="relative">
                                <img src={review.user.avatar} className="w-10 h-10 rounded-full bg-gray-200 object-cover" alt={review.user.name} />
                                {review.user.verified && (
                                    <div className="absolute -bottom-1 -right-1 bg-primary text-white rounded-full p-[2px] border-2 border-white dark:border-surface-dark flex items-center justify-center">
                                        <Icon name="check" size={10} className="font-bold" />
                                    </div>
                                )}
                            </div>
                            <div className="flex flex-col">
                                <span className="text-sm font-bold text-slate-900 dark:text-white">{review.user.name}</span>
                                <span className="text-xs text-gray-500 font-medium">Reviewer stats: {review.user.stats?.reviews || 12} reviews</span>
                            </div>
                        </div>
                        <Button variant="outline" className="!h-8 !px-3 !text-xs !rounded-lg">Follow</Button>
                    </div>

                    <div className="mb-5">
                         <p className="text-slate-700 dark:text-slate-300 text-[16px] leading-relaxed whitespace-pre-line">
                            {review.text}
                         </p>
                    </div>

                    {review.images && (
                        <div className="flex gap-3 overflow-x-auto no-scrollbar pb-2 mb-4 -mx-1 px-1">
                            {review.images.map((img: string, i: number) => (
                                <div key={i} className="flex-none w-60 aspect-video rounded-xl bg-gray-100 dark:bg-gray-800 overflow-hidden relative border border-gray-100 dark:border-gray-700">
                                    <img src={img} className="w-full h-full object-cover" alt="Proof" />
                                </div>
                            ))}
                        </div>
                    )}

                    {/* AI Analysis Section Removed */}

                    <div className="flex items-center justify-between pt-4 border-t border-gray-100 dark:border-white/5">
                        <div className="flex items-center gap-2">
                             <button 
                                onClick={handleLike}
                                className={`flex items-center gap-2 px-4 py-2 rounded-full transition-all active:scale-95 ${hasLiked ? 'bg-primary/10 text-primary' : 'bg-gray-50 dark:bg-white/5 text-gray-500 hover:bg-gray-100 dark:hover:bg-white/10'}`}
                             >
                                <Icon name="thumb_up" filled={hasLiked} size={20} />
                                <span className="text-sm font-bold">{likes}</span>
                             </button>
                             <button className="flex items-center gap-2 px-4 py-2 rounded-full bg-gray-50 dark:bg-white/5 text-gray-500 hover:bg-gray-100 dark:hover:bg-white/10 transition-all">
                                <Icon name="chat_bubble" size={20} />
                                <span className="text-sm font-bold">{commentsList.length}</span>
                             </button>
                        </div>
                    </div>
                </article>

                {/* Developer/Official Response */}
                {review.isScam && (
                     <article className="relative bg-red-500/5 rounded-2xl border border-red-500/20 p-5 overflow-hidden">
                        <div className="flex items-start gap-3">
                            <div className="shrink-0 mt-1">
                                <Icon name="security" className="text-red-500" />
                            </div>
                            <div>
                                <h4 className="font-bold text-red-500 text-sm mb-1">Safety Warning</h4>
                                <p className="text-sm text-red-900/80 dark:text-red-200/80 leading-relaxed">
                                    This number has been flagged by multiple users as a scam. Do not provide personal information.
                                </p>
                            </div>
                        </div>
                     </article>
                )}

                {/* Comments */}
                <section className="flex flex-col gap-4 mt-2">
                    <h4 className="text-sm font-bold text-gray-500 uppercase tracking-wider mb-2 px-1">Discussion</h4>

                    {/* Add Comment Input */}
                    <div className="bg-white dark:bg-surface-dark p-4 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-800">
                        {currentUser ? (
                            <div className="flex gap-3">
                                <img src={currentUser.avatar} className="w-8 h-8 rounded-full bg-gray-200 object-cover shrink-0" alt={currentUser.name} />
                                <div className="flex-1 flex flex-col gap-2">
                                    <textarea 
                                        value={commentText}
                                        onChange={(e) => setCommentText(e.target.value)}
                                        placeholder="Add a comment..." 
                                        className="w-full bg-gray-50 dark:bg-background-dark border-none rounded-xl p-3 text-sm focus:ring-1 focus:ring-primary text-slate-900 dark:text-white placeholder-gray-500 resize-none h-20"
                                    />
                                    <div className="flex justify-end">
                                        <Button 
                                            className="!h-8 !px-4 !text-xs !rounded-lg"
                                            onClick={handlePostComment}
                                            isLoading={isPosting}
                                            disabled={!commentText.trim()}
                                        >
                                            Post
                                        </Button>
                                    </div>
                                </div>
                            </div>
                        ) : (
                            <div className="flex flex-col items-center justify-center py-2 text-center">
                                <p className="text-sm text-gray-500 mb-3">Log in to join the conversation</p>
                                <Button variant="outline" onClick={login} className="!h-9">
                                    Sign In
                                </Button>
                            </div>
                        )}
                    </div>

                    {commentsList.map(comment => (
                        <div key={comment.id} className="flex gap-3 animate-fade-in">
                            <div className="w-8 h-8 rounded-full bg-gray-200 overflow-hidden shrink-0 mt-1">
                                <img src={comment.user.avatar} className="w-full h-full object-cover" alt="User" />
                            </div>
                            <div className="flex-1 bg-white dark:bg-surface-dark p-3 rounded-2xl rounded-tl-none shadow-sm border border-gray-100 dark:border-gray-800">
                                <div className="flex justify-between items-baseline mb-1">
                                    <span className="text-sm font-bold text-slate-900 dark:text-white">{comment.user.name}</span>
                                    <span className="text-[10px] text-gray-400">{comment.timeAgo}</span>
                                </div>
                                <p className="text-sm text-slate-600 dark:text-slate-300 leading-relaxed">{comment.text}</p>
                            </div>
                        </div>
                    ))}
                </section>
            </main>
        </div>
    );
};

