import { getFirestore } from "firebase/firestore";

const firebaseConfig = {
  apiKey: "AIzaSyDFtRrOXpmmLiI0ZDTOXFI9ZOvLZOZ_dq0",
  authDomain: "calculators-b3a5e.firebaseapp.com",
