    timestamp?: number;
}

import { Review, User, Comment } from '../types';
import { auth, db } from './firebase';
import { 
    signInWithEmailAndPassword, 
    createUserWithEmailAndPassword, 
    signOut, 
    updateProfile,
    onAuthStateChanged
} from 'firebase/auth';
import { 
    collection, 
    doc, 
    getDoc, 
    getDocs, 
    setDoc, 
    addDoc, 
    query, 
    where, 
    orderBy, 
    limit, 
    updateDoc, 
    increment, 
    serverTimestamp,
    Timestamp 
} from 'firebase/firestore';
import { REVIEW_CONFIG as DEFAULT_CONFIG } from './reviewConfig';
import { GoogleGenAI } from "@google/genai";

// --- UTILS ---

// Search Tokenizer: Creates an array of searchable terms
const createKeywords = (str: string): string[] => {
    if (!str) return [];
    const arr = [];
    let cur = '';
    const s = str.toLowerCase();
    for (let i = 0; i < s.length; i++) {
        cur += s[i];
        if (cur.length >= 2) arr.push(cur); // Create partial matches "te", "tes", "test"
    }
    // Add individual words
    s.split(' ').forEach(word => {
        if(word.length > 2) arr.push(word);
    });
    return [...new Set(arr)];
};

// Date Formatter
const timeAgo = (date: any) => {
    const timestamp = date instanceof Timestamp ? date.toMillis() : date;
    const seconds = Math.floor((Date.now() - timestamp) / 1000);
    let interval = seconds / 31536000;
    if (interval > 1) return Math.floor(interval) + "y ago";
    interval = seconds / 2592000;
    if (interval > 1) return Math.floor(interval) + "mo ago";
    interval = seconds / 86400;
    if (interval > 1) return Math.floor(interval) + "d ago";
    interval = seconds / 3600;
    if (interval > 1) return Math.floor(interval) + "h ago";
    interval = seconds / 60;
    if (interval > 1) return Math.floor(interval) + "m ago";
    return "Just now";
};

// --- API SERVICE ---

export const api = {
    auth: {
        login: async (email: string, pass: string): Promise<User> => {
            // For demo purposes, we allow quick sign in or use firebase
            try {
                const userCredential = await signInWithEmailAndPassword(auth, email, pass);
                const u = userCredential.user;
                return {
                    id: u.uid,
                    name: u.displayName || 'User',
                    handle: u.email || '',
                    email: u.email || '',
                    avatar: u.photoURL || `https://ui-avatars.com/api/?name=${u.email}`,
                    verified: false
                };
            } catch (error: any) {
                // If user not found, try to create (Auto-signup for demo ease)
                if (error.code === 'auth/user-not-found' || error.code === 'auth/invalid-credential') {
                    const newUser = await createUserWithEmailAndPassword(auth, email, pass);
                    // Set default name
                    await updateProfile(newUser.user, { displayName: email.split('@')[0] });
                     return {
                        id: newUser.user.uid,
                        name: email.split('@')[0],
                        handle: email,
                        email: email,
                        avatar: `https://ui-avatars.com/api/?name=${email}`,
                        verified: false
                    };
                }
                throw error;
            }
        },
        logout: async () => {
            await signOut(auth);
        },
        // Observe Auth State
        onStateChange: (callback: (user: User | null) => void) => {
            return onAuthStateChanged(auth, (u) => {
                if (u) {
                    callback({
                        id: u.uid,
                        name: u.displayName || 'User',
                        handle: u.email || '',
                        email: u.email || '',
                        avatar: u.photoURL || `https://ui-avatars.com/api/?name=${u.email || 'User'}`,
                        verified: false
                    });
                } else {
                    callback(null);
                }
            });
        },
        sendOtp: async (phone: string): Promise<boolean> => {
            return true; // Mock: Firebase Phone Auth requires Recapcha verifier in UI, keeping mock for simplicity
        },
        verifyOtp: async (phone: string, code: string): Promise<boolean> => {
             if (code === '123456') return true;
             throw new Error("Invalid Code");
        }
    },

    config: {
        // Core Logic: Load config from Firestore to Cache, or seed if empty
        get: async (): Promise<any[]> => {
            const CONFIG_CACHE_KEY = 'reviewhub_config_cache';
            const cache = localStorage.getItem(CONFIG_CACHE_KEY);

            // 1. Try Cache first (valid for 1 hour)
            if (cache) {
                const { data, timestamp } = JSON.parse(cache);
                if (Date.now() - timestamp < 3600000) {
                    return data;
                }
            }

            try {
                // 2. Fetch from Firestore
                const docRef = doc(db, "reviewhub_config", "app_settings");
                const docSnap = await getDoc(docRef);

                if (docSnap.exists()) {
                    const data = docSnap.data().categories;
                    localStorage.setItem(CONFIG_CACHE_KEY, JSON.stringify({ data, timestamp: Date.now() }));
                    return data;
                } else {
                    // 3. Seed if empty (First run)
                    await setDoc(docRef, { 
                        categories: DEFAULT_CONFIG,
                        version: "1.0",
                        updatedAt: serverTimestamp() 
                    });
                    return DEFAULT_CONFIG;
                }
            } catch (e) {
                console.error("Config load failed, using fallback", e);
                return DEFAULT_CONFIG;
            }
        }
    },

    reviews: {
        getAll: async (filter: string = 'All'): Promise<Review[]> => {
            try {
                const reviewsRef = collection(db, "reviewhub");
                let q = query(reviewsRef, orderBy("timestamp", "desc"), limit(50));

                if (filter !== 'All') {
                    if (filter === 'High Risk') {
                        q = query(reviewsRef, where("isScam", "==", true), orderBy("timestamp", "desc"), limit(50));
                    } else {
                        // Simple client-side filter simulation for categories as Firestore requires composite indexes for everything
                        // In production, we would create indexes for "entityType"
                         q = query(reviewsRef, where("entityType", "==", filter), orderBy("timestamp", "desc"), limit(50));
                    }
                }

                const querySnapshot = await getDocs(q);
                return querySnapshot.docs.map(doc => {
                    const data = doc.data();
                    return {
                        ...data,
                        id: doc.id,
                        date: timeAgo(data.timestamp)
                    } as Review;
                });
            } catch (e) {
                console.error("Error fetching reviews:", e);
                return [];
            }
        },

        create: async (data: Partial<Review>): Promise<Review> => {
            const newReview = {
                entityName: data.entityName || 'Unknown',
                entityType: data.entityType || 'General',
                rating: data.rating || 0,
                timestamp: serverTimestamp(), // Use server time
                text: data.text || '',
                likes: 0,
                comments: 0,
                user: data.user, // Passed from context
                images: data.images || [],
                tags: data.tags || [],
                meta: data.meta || {}, 
                isScam: data.isScam || false,
                keywords: createKeywords(data.entityName || '') // For search
            };

            const docRef = await addDoc(collection(db, "reviewhub"), newReview);

            return {
                ...newReview,
                id: docRef.id,
                date: 'Just now',
                timestamp: Date.now() // Optimistic return
            } as Review;
        },

        vote: async (reviewId: string, type: 'up' | 'down'): Promise<number> => {
            const reviewRef = doc(db, "reviewhub", reviewId);
            await updateDoc(reviewRef, {
                likes: increment(type === 'up' ? 1 : -1)
            });
            return 0; // Return value not strictly needed as UI is optimistic
        },

        addComment: async (reviewId: string, text: string, user: User): Promise<Comment> => {
            const commentData = {
                user,
                text,
                likes: 0,
                timestamp: serverTimestamp()
            };

            // Store comment in subcollection
            const commentRef = await addDoc(collection(db, "reviewhub", reviewId, "comments"), commentData);

            // Update main review comment count
            const reviewRef = doc(db, "reviewhub", reviewId);
            await updateDoc(reviewRef, { comments: increment(1) });

            return {
                ...commentData,
                id: commentRef.id,
                timeAgo: 'Just now'
            } as Comment;
        },

        getComments: async (reviewId: string): Promise<Comment[]> => {
             const q = query(collection(db, "reviewhub", reviewId, "comments"), orderBy("timestamp", "desc"));
             const snap = await getDocs(q);
             return snap.docs.map(d => ({
                 ...d.data(),
                 id: d.id,
                 timeAgo: timeAgo(d.data().timestamp)
             })) as Comment[];
        }
    },

    search: {
        query: async (term: string): Promise<Review[]> => {
            if (!term || term.length < 2) return [];
            const searchTerm = term.toLowerCase();

            try {
                // Basic Keyword Search
                const q = query(
                    collection(db, "reviewhub"), 
                    where("keywords", "array-contains", searchTerm),
                    limit(20)
                );

                const snap = await getDocs(q);
                return snap.docs.map(doc => {
                    const data = doc.data();
                    return {
                        ...data,
                        id: doc.id,
                        date: timeAgo(data.timestamp)
                    } as Review;
                });
            } catch (e) {
                console.error("Search failed", e);
                return [];
            }
        }
    },

    ai: {
        analyzeReview: async (text: string, entity: string): Promise<string> => {
            if (!process.env.API_KEY) {
                return "AI Analysis Unavailable: API Key missing.";
            }

            try {
                const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
                const response = await ai.models.generateContent({
                    model: 'gemini-3-flash-preview',
                    contents: `Analyze review for "${entity}": "${text}". Give trust score (1-10) and summary.`,
                });
                return response.text || "Unable to generate analysis.";
            } catch (error) {
                return "AI Analysis failed temporarily.";
            }
        }
    }
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { AppContextType, ViewState, User, ToastMessage } from '../types';
import { api } from '../services/api';
import { REVIEW_CONFIG } from '../services/reviewConfig';

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    // --- Navigation State ---
    const [currentView, setView] = useState<ViewState>('HOME');
    const [viewData, setViewData] = useState<any>(null);
    const [history, setHistory] = useState<{view: ViewState, data: any}[]>([]);

    // --- User State ---
    const [currentUser, setCurrentUser] = useState<User | null>(null);

    // --- Theme State ---
    const [isDarkMode, setIsDarkMode] = useState(true);

    // --- Toast State ---
    const [toasts, setToasts] = useState<ToastMessage[]>([]);

    // --- Dynamic Config State ---
    const [config, setConfig] = useState({ categories: REVIEW_CONFIG, loaded: false });

    // Bootstrap
    useEffect(() => {
        // 1. Auth Listener
        const unsubscribe = api.auth.onStateChange((user) => {
            setCurrentUser(user);
        });

        // 2. Load Config from Firestore/Cache
        const loadConfig = async () => {
            try {
                const categories = await api.config.get();
                setConfig({ categories, loaded: true });
            } catch (e) {
                console.error("Config load error", e);
                // Fallback is already set in initial state
            }
        };
        loadConfig();

        // 3. Theme
        if (isDarkMode) {
            document.documentElement.classList.add('dark');
        } else {
            document.documentElement.classList.remove('dark');
        }

        return () => unsubscribe();
    }, [isDarkMode]);

    const navigate = (view: ViewState, data?: any) => {
        if (view === 'WRITE_REVIEW_MODAL') {
             setView('WRITE_REVIEW_MODAL');
             return;
        }
        setHistory(prev => [...prev, { view: currentView, data: viewData }]);
        setViewData(data);
        setView(view);
        window.scrollTo(0, 0);
    };

    const login = async () => {
        // For demo, using hardcoded credential. In real app, modal handles input
        try {
            await api.auth.login("demo@reviewhub.com", "password123");
            showToast(`Welcome!`, 'success');
        } catch (e) {
            showToast("Login failed", "error");
        }
    };

    const logout = async () => {
        await api.auth.logout();
        navigate('HOME');
        showToast('Logged out successfully', 'info');
    };

    const toggleTheme = () => setIsDarkMode(!isDarkMode);

    const showToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
        const id = Math.random().toString(36).substr(2, 9);
        setToasts(prev => [...prev, { id, message, type }]);
        setTimeout(() => {
            setToasts(prev => prev.filter(t => t.id !== id));
        }, 3000);
    };

    return (
        <AppContext.Provider value={{
            currentView,
            viewData,
            navigate,
            currentUser,
            login,
            logout,
            showToast,
            isDarkMode,
            toggleTheme,
            config
        }}>
            {children}

            {/* Global Toast Render */}
            <div className="fixed top-4 left-1/2 -translate-x-1/2 z-[100] flex flex-col gap-2 w-[90%] max-w-sm pointer-events-none">
                {toasts.map(toast => (
                    <div 
                        key={toast.id}
                        className={`animate-fade-in px-4 py-3 rounded-xl shadow-xl flex items-center gap-3 border pointer-events-auto backdrop-blur-md ${
                            toast.type === 'success' ? 'bg-green-500/90 text-white border-green-600' :
                            toast.type === 'error' ? 'bg-red-500/90 text-white border-red-600' :
                            'bg-slate-800/90 text-white border-slate-700'
                        }`}
                    >
                         <span className="material-symbols-outlined text-[20px]">
                            {toast.type === 'success' ? 'check_circle' : toast.type === 'error' ? 'error' : 'info'}
                         </span>
                         <span className="text-sm font-medium">{toast.message}</span>
                    </div>
                ))}
            </div>
        </AppContext.Provider>
    );
};

export const useApp = () => {
    const context = useContext(AppContext);
    if (!context) throw new Error('useApp must be used within AppProvider');
    return context;
};

import React, { useState, useEffect } from 'react';
import { Icon, Button } from '../components/Shared';
import { api } from '../services/api';
import { useApp } from '../context/Store';
import { CategoryConfig } from '../services/reviewConfig';

export const WriteReviewModal = ({ onClose }: { onClose: () => void }) => {
    const { showToast, config, currentUser } = useApp();
    const [step, setStep] = useState(0); // 0: Category, 1: Details
    const [isLoading, setIsLoading] = useState(false);

    // State
    const [selectedCategory, setSelectedCategory] = useState<CategoryConfig | null>(null);
    const [entityName, setEntityName] = useState(''); 

    // Dynamic Extras
    const [extraData, setExtraData] = useState<Record<string, string>>({});

    const [recommendedContact, setRecommendedContact] = useState('');
    const [isSameContact, setIsSameContact] = useState(false); 

    const [selectedPlatform, setSelectedPlatform] = useState('');
    const [selectedIssues, setSelectedIssues] = useState<string[]>([]);
    const [rating, setRating] = useState(0);
    const [description, setDescription] = useState('');

    // Reset issues when rating changes significantly
    useEffect(() => {
        setSelectedIssues([]);
    }, [rating < 4]);

    useEffect(() => {
        const phoneValue = extraData['phoneNumber'];
        if (isSameContact && phoneValue) {
            setRecommendedContact(phoneValue);
        }
    }, [extraData, isSameContact]);

    const handleExtraChange = (id: string, value: string) => {
        setExtraData(prev => ({ ...prev, [id]: value }));

        if (id === 'phoneNumber' && isSameContact) {
            setRecommendedContact(value);
        }
    };

    const toggleIssue = (issue: string) => {
        setSelectedIssues(prev => 
            prev.includes(issue) ? prev.filter(i => i !== issue) : [...prev, issue]
        );
    };

    const handleSubmit = async () => {
        if (!entityName || rating === 0 || !selectedCategory || !currentUser) {
            showToast("Please fill in the required fields", "error");
            return;
        }

        setIsLoading(true);
        try {
            // Construct structured Data
            const metaData: any = {
                platform: selectedPlatform,
                issues: selectedIssues,
                category: selectedCategory.id,
                ...extraData 
            };

            if (rating >= 4 && recommendedContact) {
                metaData.recommendedContact = recommendedContact;
            }

            const isScam = selectedIssues.some(i => 
                ['Scam', 'Fraud', 'No Delivery', 'Fake Item', 'Lottery Scam', 'Bank OTP Scam', 'Blocked Me'].some(keyword => i.includes(keyword))
            ) || selectedCategory.id === 'phone_scam' || rating === 1;

            const tags = [
                ...(isScam ? ['High Risk'] : []),
                ...(rating >= 4 ? ['Recommended'] : []),
                ...(selectedPlatform ? [selectedPlatform] : []),
                selectedCategory.label
            ];

            await api.reviews.create({
                entityName: entityName,
                entityType: selectedCategory.label,
                rating: rating,
                text: description,
                isScam: isScam,
                tags: tags,
                meta: metaData,
                user: currentUser
            });

            showToast("Review published successfully!", "success");
            onClose();
        } catch (e) {
            console.error(e);
            showToast("Failed to publish review", "error");
        } finally {
            setIsLoading(false);
        }
    };

    const renderCategoryStep = () => (
        <div className="animate-fade-in px-1">
            <h3 className="text-xl font-bold text-white mb-2">What kind of review is this?</h3>
            <p className="text-gray-400 text-sm mb-6">Select a category to help us ask the right questions.</p>

            <div className="grid grid-cols-2 gap-3 pb-8">
                {config.categories.map((cat: CategoryConfig) => (
                    <button
                        key={cat.id}
                        onClick={() => { setSelectedCategory(cat); setStep(1); }}
                        className={`flex flex-col items-center justify-center p-4 rounded-2xl border transition-all active:scale-95 hover:bg-white/5 ${cat.color}`}
                    >
                        <Icon name={cat.icon} size={32} className="mb-2" />
                        <span className="font-bold text-sm text-gray-200">{cat.label}</span>
                    </button>
                ))}
            </div>
        </div>
    );

    const renderDetailsStep = () => {
        if (!selectedCategory) return null;

        let displayedTags: string[] = [];
        if (rating > 0) {
            displayedTags = rating >= 4 ? selectedCategory.tags.positive : selectedCategory.tags.negative;
        }

        return (
            <div className="animate-slide-up space-y-6 pb-20">
                {/* 1. Identity Inputs */}
                <div>
                    <label className="block text-xs font-bold uppercase tracking-wider text-gray-400 mb-2">{selectedCategory.inputLabel} <span className="text-red-500">*</span></label>
                    <input 
                        className="w-full bg-[#1c2128] border border-gray-700 rounded-xl px-4 py-4 text-white placeholder-gray-500 focus:outline-none focus:ring-2 focus:ring-primary/50 text-lg transition-all" 
                        placeholder={selectedCategory.inputPlaceholder}
                        value={entityName}
                        onChange={(e) => setEntityName(e.target.value)}
                        autoFocus
                    />
                </div>

                {/* Conditional Inputs from Config (Dynamic) */}
                {selectedCategory.secondaryInputs && selectedCategory.secondaryInputs.length > 0 && (
                    <div className="grid grid-cols-2 gap-4">
                        {selectedCategory.secondaryInputs.map(input => (
                             <div key={input.id}>
                                <label className="block text-xs font-bold uppercase tracking-wider text-gray-500 mb-2">{input.label}</label>
                                <input 
                                    className="w-full bg-[#1c2128] border border-gray-700 rounded-xl px-4 py-3 text-white placeholder-gray-600 focus:outline-none focus:ring-2 focus:ring-primary/50 text-sm" 
                                    placeholder={input.placeholder}
                                    type={input.type}
                                    value={extraData[input.id] || ''}
                                    onChange={(e) => handleExtraChange(input.id, e.target.value)}
                                />
                            </div>
                        ))}
                    </div>
                )}

                {/* 2. Platform Selection */}
                {selectedCategory.platforms.length > 0 && (
                    <div>
                        <label className="block text-xs font-bold uppercase tracking-wider text-gray-400 mb-3">Platform / Method</label>
                        <div className="flex flex-wrap gap-2">
                            {selectedCategory.platforms.map((p: string) => (
                                <button
                                    key={p}
                                    onClick={() => setSelectedPlatform(p)}
                                    className={`px-4 py-2 rounded-full text-sm font-medium border transition-all ${
                                        selectedPlatform === p 
                                        ? 'bg-primary border-primary text-white shadow-lg shadow-primary/20' 
                                        : 'bg-transparent border-gray-600 text-gray-300 hover:border-gray-400'
                                    }`}
                                >
                                    {p}
                                </button>
                            ))}
                        </div>
                    </div>
                )}

                {/* 3. Rating */}
                <div className="flex flex-col items-center py-2">
                    <div className="flex items-center gap-3">
                        {[1, 2, 3, 4, 5].map((star) => (
                            <button 
                                key={star} 
                                onClick={() => setRating(star)} 
                                className="group transition-transform active:scale-95 focus:outline-none"
                            >
                                <Icon 
                                    name="star" 
                                    filled={star <= rating} 
                                    size={36} 
                                    className={`transition-all duration-200 ${
                                        star <= rating 
                                        ? "text-amber-400 drop-shadow-[0_0_8px_rgba(251,191,36,0.3)]" 
                                        : "text-gray-700 dark:text-gray-600 hover:text-gray-500"
                                    }`} 
                                />
                            </button>
                        ))}
                    </div>
                    <div className={`mt-3 h-5 flex items-center justify-center transition-all duration-300 ${rating > 0 ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-2'}`}>
                        <span className={`text-sm font-bold tracking-wider ${
                            rating >= 4 ? 'text-green-400' : 
                            rating === 3 ? 'text-yellow-400' : 
                            'text-red-400'
                        }`}>
                            {rating === 1 ? "Terrible" : rating === 2 ? "Bad" : rating === 3 ? "Okay" : rating === 4 ? "Good" : rating === 5 ? "Excellent" : ""}
                        </span>
                    </div>
                </div>

                {/* 4. Dynamic Highlights */}
                {rating > 0 && displayedTags.length > 0 && (
                    <div className="animate-fade-in">
                        <label className="block text-xs font-bold uppercase tracking-wider text-gray-400 mb-3">
                            {rating >= 4 ? "What went well?" : "What went wrong?"}
                        </label>
                        <div className="flex flex-wrap gap-2">
                            {displayedTags.map((issue: string) => {
                                const isSelected = selectedIssues.includes(issue);
                                const isPositive = rating >= 4;

                                return (
                                    <button
                                        key={issue}
                                        onClick={() => toggleIssue(issue)}
                                        className={`px-4 py-2 rounded-full text-sm font-medium border transition-all ${
                                            isSelected 
                                                ? (isPositive 
                                                    ? 'bg-green-500/20 border-green-500 text-green-400' 
                                                    : 'bg-red-500/20 border-red-500 text-red-400')
                                                : 'bg-transparent border-gray-700 text-gray-400 hover:border-gray-500'
                                        }`}
                                    >
                                        {issue}
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                )}

                {/* 5. Conditional Contact Info */}
                {rating >= 4 && (
                    <div className="animate-fade-in bg-green-500/5 p-4 rounded-xl border border-green-500/20">
                        <div className="flex items-start gap-3 mb-3">
                            <Icon name="verified" className="text-green-500 mt-1" size={20} />
                            <div>
                                <h4 className="font-bold text-green-400 text-sm">Help others find this!</h4>
                                <p className="text-xs text-gray-400">Add a contact number so others can hire this person/service.</p>
                            </div>
                        </div>

                        {extraData['phoneNumber'] && extraData['phoneNumber'].length > 0 && (
                            <label className="flex items-center gap-2 mb-3 cursor-pointer group w-fit select-none">
                                <div className={`w-4 h-4 rounded border flex items-center justify-center transition-colors ${isSameContact ? 'bg-green-500 border-green-500' : 'border-gray-500 group-hover:border-green-500'}`}>
                                    {isSameContact && <Icon name="check" size={12} className="text-white font-bold" />}
                                </div>
                                <input 
                                    type="checkbox" 
                                    className="hidden"
                                    checked={isSameContact}
                                    onChange={(e) => setIsSameContact(e.target.checked)}
                                />
                                <span className={`text-xs font-medium transition-colors ${isSameContact ? 'text-green-400' : 'text-gray-400 group-hover:text-gray-300'}`}>
                                    Same as above
                                </span>
                            </label>
                        )}

                        <input 
                            className="w-full bg-[#111418] border border-gray-700 rounded-lg px-4 py-3 text-white placeholder-gray-600 focus:outline-none focus:ring-1 focus:ring-green-500 text-sm" 
                            placeholder="Recommended Contact Number (Optional)"
                            type="tel"
                            value={recommendedContact}
                            onChange={(e) => {
                                setRecommendedContact(e.target.value);
                                if (isSameContact) setIsSameContact(false);
                            }}
                        />
                    </div>
                )}

                {/* 6. Description */}
                <div>
                    <label className="block text-xs font-bold uppercase tracking-wider text-gray-400 mb-2">Description (Optional)</label>
                    <textarea 
                        className="w-full bg-[#1c2128] border border-gray-700 rounded-xl px-4 py-4 h-32 resize-none focus:outline-none focus:ring-2 focus:ring-primary/50 text-white placeholder-gray-500 text-base" 
                        placeholder="Tell others about your experience..."
                        value={description}
                        onChange={(e) => setDescription(e.target.value)} 
                    ></textarea>
                </div>
            </div>
        );
    };

    return (
        <div className="fixed inset-0 z-50 flex flex-col justify-end">
            <div className="absolute inset-0 bg-black/80 backdrop-blur-sm transition-opacity" onClick={onClose}></div>

            <div className="relative w-full bg-surface-dark dark:bg-[#111418] rounded-t-3xl shadow-2xl flex flex-col h-[92vh] animate-slide-up text-white overflow-hidden border-t border-white/10">
                {/* Header */}
                <div className="px-6 py-4 flex items-center justify-between shrink-0 border-b border-white/5 bg-[#111418] z-20">
                    <div className="flex items-center gap-3">
                        {step > 0 && (
                            <button onClick={() => setStep(step - 1)} className="p-1 rounded-full hover:bg-white/10 text-gray-400">
                                <Icon name="arrow_back" size={20} />
                            </button>
                        )}
                        <h2 className="text-lg font-bold tracking-tight">
                            {step === 0 ? "New Review" : selectedCategory?.title}
                        </h2>
                    </div>
                    <button onClick={onClose} className="p-2 -mr-2 text-gray-400 hover:text-white rounded-full hover:bg-white/10 transition-colors">
                        <Icon name="close" />
                    </button>
                </div>

                {/* Content */}
                <div className="flex-1 overflow-y-auto px-6 py-6 no-scrollbar relative">
                    {step === 0 && renderCategoryStep()}
                    {step === 1 && renderDetailsStep()}
                </div>

                {/* Footer Actions */}
                {step > 0 && (
                    <div className="p-4 border-t border-white/10 bg-[#111418] z-20 pb-8">
                        <Button 
                            variant="primary" 
                            onClick={handleSubmit} 
                            isLoading={isLoading}
                            className="w-full text-base"
                            disabled={!entityName || rating === 0}
                        >
                            Submit Review
                        </Button>
                    </div>
                )}
            </div>
        </div>
    );
};

