const textLkToken = defineSecret("TEXT_LK_API_TOKEN");
const geminiApiKey = defineSecret("GEMINI_API_KEY");

const MAX_DAILY_SMS_PER_USER = 5;
const SMS_COOLDOWN_SECONDS = 60;
const MAX_VERIFY_ATTEMPTS = 3;
const DEV_FALLBACK_TOKEN = "2725|pQw9fvkKFD4fCSElwxnOVwcF8SdB4b5mxIfxnGD7d2163fa2";

async function checkUserRateLimit(uid) {
    const rateRef = db.collection("rate_limits").doc(uid);
    const doc = await rateRef.get();
    const now = Date.now();
    const ONE_DAY_MS = 24 * 60 * 60 * 1000;
    let data = doc.data();
    if (!data || now > data.resetAt) {
        data = { count: 0, resetAt: now + ONE_DAY_MS };
    }
    if (data.count >= MAX_DAILY_SMS_PER_USER) {
        throw new HttpsError('resource-exhausted', `Daily SMS limit reached (${MAX_DAILY_SMS_PER_USER}). Try again in 24 hours.`);
    }
    return { rateRef, data };
}

exports.requestOtp = onCall({ secrets: [textLkToken] }, async (request) => {
    const uid = request.auth ? request.auth.uid : null;
    if (!uid) throw new HttpsError("unauthenticated", "You must be logged in.");
    const rawPhone = request.data.phone;
    if (!rawPhone) throw new HttpsError("invalid-argument", "Phone number required");
    const phoneRegex = /^947\d{8}$/;
    if (!phoneRegex.test(rawPhone)) {
        throw new HttpsError("invalid-argument", "Invalid format. Use 947XXXXXXXX.");
    }
    const { rateRef, data: rateData } = await checkUserRateLimit(uid);
    const otpRef = db.collection("otp_requests").doc(rawPhone);
    const otpDoc = await otpRef.get();
    if (otpDoc.exists) {
        const lastRequest = otpDoc.data().createdAt.toMillis();
        const timeDiff = (Date.now() - lastRequest) / 1000;
        if (timeDiff < SMS_COOLDOWN_SECONDS) {
            throw new HttpsError("resource-exhausted", `Please wait ${Math.ceil(SMS_COOLDOWN_SECONDS - timeDiff)}s before requesting again.`);
        }
    }
    const code = Math.floor(100000 + Math.random() * 900000).toString();
    const expiresAt = Date.now() + 5 * 60 * 1000;
    try {
        const fetch = (await import("node-fetch")).default;
        let token = textLkToken.value();
        if (!token || token === "undefined") {
            token = DEV_FALLBACK_TOKEN;
        }
        const response = await fetch("https://app.text.lk/api/v3/sms/send", {
            method: "POST",
            headers: {
                "Authorization": `Bearer ${token}`,
                "Content-Type": "application/json",
                "Accept": "application/json"
            },
            body: JSON.stringify({
                recipient: rawPhone,
                sender_id: "TextLKDemo", 
                type: "plain",
                message: `Your ReviewHub verification code is: ${code}`
            })
        });
        const textResponse = await response.text();
        let result;
        try {
            result = JSON.parse(textResponse);
        } catch (e) {
            throw new Error("Invalid response from SMS provider");
        }
        if (result.status === "error" || (result.data && result.data.status === "fail")) {
            throw new HttpsError("unavailable", "SMS Provider Error: " + (result.message || "Unknown error"));
        }
        const batch = db.batch();
        batch.set(otpRef, { code, expiresAt, createdAt: admin.firestore.FieldValue.serverTimestamp(), uid: uid, attempts: 0 });
        batch.set(rateRef, { count: rateData.count + 1, resetAt: rateData.resetAt });
        await batch.commit();
        return { success: true };
    } catch (e) {
        if (e instanceof HttpsError) throw e;
        throw new HttpsError("internal", "Failed to send SMS. " + e.message);
    }
});

exports.verifyOtp = onCall(async (request) => {
    const { phone, code } = request.data;
    const uid = request.auth ? request.auth.uid : null;
    if (!uid) throw new HttpsError("unauthenticated", "User must be logged in.");
    if (!phone || !code) throw new HttpsError("invalid-argument", "Missing phone or code.");
    const docRef = db.collection("otp_requests").doc(phone);
    const docSnap = await docRef.get();
    if (!docSnap.exists) throw new HttpsError("not-found", "OTP request not found or expired.");
    const data = docSnap.data();
    if (data.uid && data.uid !== uid) throw new HttpsError("permission-denied", "This OTP was requested by a different account.");
    if (data.expiresAt < Date.now()) {
        await docRef.delete();
        throw new HttpsError("failed-precondition", "OTP expired. Request a new one.");
    }
    if (data.code !== code) {
        const newAttempts = (data.attempts || 0) + 1;
        if (newAttempts >= MAX_VERIFY_ATTEMPTS) {
            await docRef.delete();
            throw new HttpsError("resource-exhausted", "Too many failed attempts. Request a new OTP.");
        }
        await docRef.update({ attempts: newAttempts });
        throw new HttpsError("invalid-argument", `Invalid code. ${MAX_VERIFY_ATTEMPTS - newAttempts} attempts remaining.`);
    }
    await docRef.delete();
    await db.collection("users").doc(uid).set({ verified: true, phone: phone, updatedAt: admin.firestore.FieldValue.serverTimestamp() }, { merge: true });
    return { success: true };
});

exports.globalSearch = onCall({ secrets: [geminiApiKey] }, async (request) => {
    const { query: searchQuery } = request.data;
    const apiKey = geminiApiKey.value();
    if (!apiKey) throw new HttpsError("failed-precondition", "AI key not configured.");

    try {
        const ai = new GoogleGenAI({ apiKey: apiKey });
        const response = await ai.models.generateContent({
            model: "gemini-3-flash-preview",
            contents: `Investigate this entity (phone, business, or link) across the web (Facebook, Reddit, News, Consumer Forums). Summarize its reputation and any scam reports: "${searchQuery}"`,
            config: {
                tools: [{ googleSearch: {} }],
            },
        });

        const text = response.text;
        const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

        return { text, sources };
    } catch (e) {
        console.error("Global search error:", e);
        throw new HttpsError("internal", "Global search failed.");
    }
});

exports.analyzeReview = onCall({ secrets: [geminiApiKey] }, async (request) => {
    const { text, entity } = request.data;
    const apiKey = geminiApiKey.value();
    if (!apiKey) return { text: "AI Analysis unavailable." };
    try {
        const ai = new GoogleGenAI({ apiKey: apiKey });
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Analyze this review for ${entity}. Provide a trust score (1-10) and a brief summary. Text: "${text}"`,
        });
        return { text: response.text };
    } catch (e) {
        return { text: "Unable to analyze at this time." };
    }
});

exports.checkToxicity = onCall({ secrets: [geminiApiKey] }, async (request) => {
    const { text } = request.data;
    const apiKey = geminiApiKey.value();
    if (!apiKey) return { score: 0 };
    try {
        const ai = new GoogleGenAI({ apiKey: apiKey });
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Rate the toxicity of this text from 0.0 to 1.0. Return only number. Text: "${text}"`,
        });
        const score = parseFloat(response.text);
        return { score: isNaN(score) ? 0 : score };
    } catch (e) {
        return { score: 0 };
    }
});

import { Review, User, Comment, ApiService } from '../types';
import { auth, db, functions } from './firebase';
import { httpsCallable } from 'firebase/functions';
import { 
    signInWithEmailAndPassword, 
    createUserWithEmailAndPassword, 
    signOut, 
    updateProfile,
    onAuthStateChanged,
    signInWithPopup,
    GoogleAuthProvider
} from 'firebase/auth';
import { 
    collection, 
    doc, 
    getDoc, 
    getDocs, 
    setDoc, 
    addDoc, 
    query, 
    where, 
    orderBy, 
    limit, 
    updateDoc, 
    increment, 
    serverTimestamp,
    onSnapshot,
    Timestamp 
} from 'firebase/firestore';
import { REVIEW_CONFIG as DEFAULT_CONFIG } from './reviewConfig';

const createKeywords = (str: string): string[] => {
    if (!str) return [];
    const arr = [];
    let cur = '';
    const s = str.toLowerCase();
    for (let i = 0; i < s.length; i++) {
        cur += s[i];
        if (cur.length >= 2) arr.push(cur);
    }
    s.split(' ').forEach(word => {
        if(word.length > 2) arr.push(word);
    });
    return [...new Set(arr)];
};

const timeAgo = (date: any) => {
    const timestamp = date instanceof Timestamp ? date.toMillis() : date;
    const seconds = Math.floor((Date.now() - timestamp) / 1000);
    let interval = seconds / 31536000;
    if (interval > 1) return Math.floor(interval) + "y ago";
    interval = seconds / 2592000;
    if (interval > 1) return Math.floor(interval) + "mo ago";
    interval = seconds / 86400;
    if (interval > 1) return Math.floor(interval) + "d ago";
    interval = seconds / 3600;
    if (interval > 1) return Math.floor(interval) + "h ago";
    interval = seconds / 60;
    if (interval > 1) return Math.floor(interval) + "m ago";
    return "Just now";
};

export const api: ApiService = {
    auth: {
        login: async (email: string, pass: string): Promise<User> => {
            try {
                const userCredential = await signInWithEmailAndPassword(auth, email, pass);
                const u = userCredential.user;
                return {
                    id: u.uid,
                    name: u.displayName || 'User',
                    handle: u.email || '',
                    email: u.email || '',
                    avatar: u.photoURL || `https://ui-avatars.com/api/?name=${u.email}`,
                    verified: false
                };
            } catch (error: any) {
                if (error.code === 'auth/user-not-found' || error.code === 'auth/invalid-credential') {
                    const newUser = await createUserWithEmailAndPassword(auth, email, pass);
                    await updateProfile(newUser.user, { displayName: email.split('@')[0] });
                    await setDoc(doc(db, "users", newUser.user.uid), {
                        name: email.split('@')[0],
                        email: email,
                        verified: false,
                        createdAt: serverTimestamp()
                    });
                    return {
                        id: newUser.user.uid,
                        name: email.split('@')[0],
                        handle: email,
                        email: email,
                        avatar: `https://ui-avatars.com/api/?name=${email}`,
                        verified: false
                    };
                }
                throw error;
            }
        },
        loginWithGoogle: async (): Promise<User> => {
            const provider = new GoogleAuthProvider();
            try {
                const result = await signInWithPopup(auth, provider);
                const u = result.user;
                const userRef = doc(db, "users", u.uid);
                const snap = await getDoc(userRef);
                if (!snap.exists()) {
                    await setDoc(userRef, {
                        name: u.displayName,
                        email: u.email,
                        verified: false,
                        createdAt: serverTimestamp()
                    });
                }
                return {
                    id: u.uid,
                    name: u.displayName || 'User',
                    handle: u.email || '',
                    email: u.email || '',
                    avatar: u.photoURL || `https://ui-avatars.com/api/?name=${u.email}`,
                    verified: snap.exists() ? snap.data().verified : false
                };
            } catch (error: any) {
                if (error.code === 'auth/popup-blocked' || error.code === 'auth/cancelled-popup-request') {
                     throw new Error("Popup blocked or closed. Please allow popups for this site.");
                }
                throw error;
            }
        },
        logout: async () => { await signOut(auth); },
        onStateChange: (callback: (user: User | null) => void) => {
            return onAuthStateChanged(auth, (u) => {
                if (u) {
                    const unsubProfile = onSnapshot(doc(db, "users", u.uid), (docSnap) => {
                        const data = docSnap.data();
                        callback({
                            id: u.uid,
                            name: data?.name || u.displayName || 'User',
                            handle: data?.email || u.email || '',
                            email: u.email || '',
                            avatar: u.photoURL || `https://ui-avatars.com/api/?name=${u.email}`,
                            verified: data?.verified || false,
                            stats: data?.stats
                        });
                    });
                } else {
                    callback(null);
                }
            });
        },
        sendOtp: async (phone: string): Promise<boolean> => {
            try {
                let formattedPhone = phone.replace(/\D/g, ''); 
                if (formattedPhone.startsWith('0')) formattedPhone = '94' + formattedPhone.substring(1);
                const requestOtp = httpsCallable(functions, 'requestOtp');
                const response: any = await requestOtp({ phone: formattedPhone });
                return response.data?.success || false;
            } catch (e: any) {
                if (e.message && (e.message.includes("limit") || e.message.includes("wait") || e.message.includes("format"))) {
                     alert(e.message); 
                } else {
                     alert("Failed to send SMS. Please try again later.");
                }
                return false;
            }
        },
        verifyOtp: async (phone: string, code: string): Promise<boolean> => {
             let formattedPhone = phone.replace(/\D/g, ''); 
             if (formattedPhone.startsWith('0')) formattedPhone = '94' + formattedPhone.substring(1);
             try {
                 const verifyOtp = httpsCallable(functions, 'verifyOtp');
                 const response: any = await verifyOtp({ phone: formattedPhone, code });
                 return response.data?.success || false;
             } catch (e: any) {
                 if (e.message) alert(e.message);
                 throw new Error(e.message || "Invalid Code");
             }
        }
    },
    config: {
        get: async (): Promise<any[]> => {
            const CONFIG_CACHE_KEY = 'reviewhub_config_cache';
            const cache = localStorage.getItem(CONFIG_CACHE_KEY);
            if (cache) {
                const { data, timestamp } = JSON.parse(cache);
                if (Date.now() - timestamp < 3600000) return data;
            }
            try {
                const docRef = doc(db, "reviewhub_config", "app_settings");
                const docSnap = await getDoc(docRef);
                if (docSnap.exists()) {
                    const data = docSnap.data().categories;
                    localStorage.setItem(CONFIG_CACHE_KEY, JSON.stringify({ data, timestamp: Date.now() }));
                    return data;
                } else {
                    await setDoc(docRef, { categories: DEFAULT_CONFIG, version: "1.0", updatedAt: serverTimestamp() });
                    return DEFAULT_CONFIG;
                }
            } catch (e) {
                return DEFAULT_CONFIG;
            }
        }
    },
    reviews: {
        getAll: async (filter: string = 'All'): Promise<Review[]> => {
            try {
                const reviewsRef = collection(db, "reviewhub");
                const q = query(reviewsRef, orderBy("timestamp", "desc"), limit(50));
                const querySnapshot = await getDocs(q);
                const allReviews = querySnapshot.docs.map(doc => {
                    const data = doc.data();
                    return { ...data, id: doc.id, date: timeAgo(data.timestamp) } as Review;
                }).filter(r => r.status !== 'hidden');
                if (filter === 'All') return allReviews;
                if (filter === 'High Risk') return allReviews.filter(r => r.isScam === true);
                return allReviews.filter(r => r.entityType === filter);
            } catch (e) { return []; }
        },
        getUserReviews: async (userId: string): Promise<Review[]> => {
            try {
                const reviewsRef = collection(db, "reviewhub");
                const q = query(reviewsRef, where("user.id", "==", userId));
                const querySnapshot = await getDocs(q);
                return querySnapshot.docs.map(doc => {
                    const data = doc.data();
                    return { ...data, id: doc.id, date: timeAgo(data.timestamp) } as Review;
                }).sort((a, b) => b.timestamp - a.timestamp);
            } catch (e) { return []; }
        },
        create: async (data: Partial<Review>): Promise<Review> => {
            let toxicity = 0;
            if (data.text && data.text.length > 5) {
                try {
                     const checkToxicity = httpsCallable(functions, 'checkToxicity');
                     const result: any = await checkToxicity({ text: data.text });
                     toxicity = result.data?.score || 0;
                     if (toxicity > 0.7) throw new Error("Review rejected: Content flagged as toxic/harmful.");
                } catch (e: any) {
                    if (e.message.includes("Review rejected")) throw e;
                }
            }
            const newReview = {
                entityName: data.entityName || 'Unknown',
                entityType: data.entityType || 'General',
                rating: data.rating || 0,
                timestamp: serverTimestamp(),
                text: data.text || '',
                likes: 0,
                comments: 0,
                user: data.user!,
                images: data.images || [],
                tags: data.tags || [],
                meta: data.meta || {}, 
                isScam: data.isScam || false,
                keywords: createKeywords(data.entityName || ''),
                status: 'active',
                toxicityScore: toxicity,
                verifiedBadge: data.user?.verified || false
            };
            const docRef = await addDoc(collection(db, "reviewhub"), newReview);
            return { ...newReview, id: docRef.id, date: 'Just now', timestamp: Date.now() } as Review;
        },
        vote: async (reviewId: string, type: 'up' | 'down'): Promise<number> => {
            const reviewRef = doc(db, "reviewhub", reviewId);
            await updateDoc(reviewRef, { likes: increment(type === 'up' ? 1 : -1) });
            return 0;
        },
        addComment: async (reviewId: string, text: string, user: User): Promise<Comment> => {
            const commentData = { user, text, likes: 0, timestamp: serverTimestamp() };
            const commentRef = await addDoc(collection(db, "reviewhub", reviewId, "comments"), commentData);
            await updateDoc(doc(db, "reviewhub", reviewId), { comments: increment(1) });
            return { ...commentData, id: commentRef.id, timeAgo: 'Just now' } as Comment;
        },
        getComments: async (reviewId: string): Promise<Comment[]> => {
             const q = query(collection(db, "reviewhub", reviewId, "comments"), orderBy("timestamp", "desc"));
             const snap = await getDocs(q);
             return snap.docs.map(d => ({ ...d.data(), id: d.id, timeAgo: timeAgo(d.data().timestamp) })) as Comment[];
        },
        report: async (reviewId: string, reason: string): Promise<void> => {
             await addDoc(collection(db, "reviewhub_flags"), { reviewId, reason, timestamp: serverTimestamp(), status: 'pending' });
        }
    },
    search: {
        query: async (term: string): Promise<Review[]> => {
            if (!term || term.length < 2) return [];
            const searchTerm = term.toLowerCase();
            try {
                const q = query(collection(db, "reviewhub"), where("keywords", "array-contains", searchTerm), limit(20));
                const snap = await getDocs(q);
                return snap.docs.map(doc => {
                    const data = doc.data();
                    return { ...data, id: doc.id, date: timeAgo(data.timestamp) } as Review;
                }).filter(r => r.status !== 'hidden');
            } catch (e) { return []; }
        }
    },
    ai: {
        analyzeReview: async (text: string, entity: string): Promise<string> => {
            try {
                const analyzeReview = httpsCallable(functions, 'analyzeReview');
                const result: any = await analyzeReview({ text, entity });
                return result.data?.text || "Analysis unavailable.";
            } catch (error) { return "AI Analysis failed temporarily."; }
        },
        checkToxicity: async (text: string): Promise<number> => {
            try {
                 const checkToxicity = httpsCallable(functions, 'checkToxicity');
                 const result: any = await checkToxicity({ text });
                 return result.data?.score || 0;
            } catch (e) { return 0; }
        },
        globalSearch: async (query: string): Promise<{ text: string, sources: any[] }> => {
            try {
                const globalSearch = httpsCallable(functions, 'globalSearch');
                const result: any = await globalSearch({ query });
                return result.data || { text: "No global info found.", sources: [] };
            } catch (e) {
                console.error("AI global search error", e);
                return { text: "Investigative search failed.", sources: [] };
            }
        }
    }
};

import React, { useState, useEffect } from 'react';
import { useApp } from '../context/Store';
import { api } from '../services/api';
import { Review } from '../types';
import { Icon, Skeleton, Button } from '../components/Shared';

export const Search = () => {
    const { navigate, showToast } = useApp();
    const [query, setQuery] = useState('');
    const [results, setResults] = useState<Review[]>([]);
    const [isSearching, setIsSearching] = useState(false);

    // Global Search States
    const [isGlobalSearching, setIsGlobalSearching] = useState(false);
    const [globalResult, setGlobalResult] = useState<{ text: string, sources: any[] } | null>(null);

    // Internal Search
    useEffect(() => {
        const timer = setTimeout(async () => {
            if (query.length > 2) {
                setIsSearching(true);
                setGlobalResult(null); // Clear previous AI results
                const data = await api.search.query(query);
                setResults(data);
                setIsSearching(false);
            } else {
                setResults([]);
                setGlobalResult(null);
            }
        }, 500);
        return () => clearTimeout(timer);
    }, [query]);

    const handleGlobalSearch = async () => {
        if (query.length < 3) return;
        setIsGlobalSearching(true);
        try {
            const response = await api.ai.globalSearch(query);
            setGlobalResult(response);
        } catch (e) {
            showToast("Investigative search failed.", "error");
        } finally {
            setIsGlobalSearching(false);
        }
    };

    return (
        <div className="flex flex-col h-full bg-background-light dark:bg-background-dark animate-fade-in pb-24">
            <header className="sticky top-0 z-50 bg-white dark:bg-background-dark border-b border-gray-100 dark:border-gray-800 pb-2">
                <div className="flex items-center px-4 pt-4 pb-2 gap-3">
                    <button onClick={() => navigate('HOME')} className="flex items-center justify-center size-10 text-primary hover:bg-slate-50 dark:hover:bg-white/5 rounded-full transition-colors shrink-0">
                        <Icon name="arrow_back" />
                    </button>
                    <div className="flex-1 relative">
                        <div className="flex w-full items-center rounded-2xl bg-slate-100 dark:bg-surface-dark h-12 px-4 focus-within:ring-2 focus-within:ring-primary/50 transition-all">
                            <Icon name="search" className="text-gray-400" size={22} />
                            <input 
                                className="w-full bg-transparent border-none focus:ring-0 text-base text-slate-900 dark:text-white placeholder-gray-400 px-3 font-normal" 
                                type="text" 
                                placeholder="Search everything..."
                                value={query}
                                onChange={(e) => setQuery(e.target.value)}
                                autoFocus
                            />
                            {query && (
                                <button onClick={() => setQuery('')}>
                                    <Icon name="cancel" filled className="text-gray-400 hover:text-gray-600" size={20} />
                                </button>
                            )}
                        </div>
                    </div>
                </div>
            </header>

            <main className="flex-1 flex flex-col p-4 gap-4 overflow-y-auto no-scrollbar">
                {/* Local Results */}
                {isSearching ? (
                    [1,2,3].map(i => <Skeleton key={i} className="h-24 w-full rounded-xl" />)
                ) : results.length > 0 ? (
                    <div className="space-y-3">
                        <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest px-1">Found in Hub</h4>
                        {results.map(result => (
                            <div 
                                key={result.id}
                                onClick={() => navigate('REVIEW_DETAILS', result)}
                                className="bg-white dark:bg-surface-dark rounded-xl p-4 shadow-sm active:scale-[0.98] transition-all cursor-pointer border border-gray-100 dark:border-gray-800"
                            >
                                <div className="flex justify-between items-start mb-1">
                                    <h3 className="font-bold text-slate-900 dark:text-white">{result.entityName}</h3>
                                    <div className="flex items-center gap-1 bg-amber-50 dark:bg-amber-900/20 px-1.5 py-0.5 rounded">
                                        <Icon name="star" filled className="text-amber-500" size={10} />
                                        <span className="text-[10px] font-bold text-amber-600">{result.rating.toFixed(1)}</span>
                                    </div>
                                </div>
                                <p className="text-sm text-slate-600 dark:text-slate-400 line-clamp-2">{result.text}</p>
                            </div>
                        ))}
                    </div>
                ) : null}

                {/* Global Search Trigger */}
                {query.length > 2 && !isSearching && (
                    <div className="mt-2 animate-fade-in">
                        <div className="bg-primary/5 dark:bg-primary/10 rounded-2xl p-5 border border-primary/20 flex flex-col items-center text-center gap-4">
                            <div className="size-12 bg-primary/20 rounded-full flex items-center justify-center text-primary">
                                <Icon name="explore" className={isGlobalSearching ? "animate-spin" : ""} />
                            </div>
                            <div>
                                <h3 className="text-sm font-bold text-slate-900 dark:text-white">Search beyond the Hub?</h3>
                                <p className="text-xs text-gray-500 mt-1 max-w-[200px]">Ask AI to search Facebook, Reddit, and forums for reports on "{query}".</p>
                            </div>
                            <Button 
                                onClick={handleGlobalSearch} 
                                isLoading={isGlobalSearching}
                                className="!h-10 !px-6 !text-xs !rounded-full"
